const HERBS=[
 {n:"黄芪",f:"甘，微温 · 归脾、肺经",x:"圆柱形切片，外皮浅黄白，断面「金盏银盘」、皮部有菊花心状裂隙，味微甜带豆腥气。",e:"补气升阳、固表止汗、利水消肿，被誉为\u201c补气之长\u201d，是气虚体质的常用之品。",s:"《神农本草经》列为上品：\u201c主痈疽久败疮……补虚。\u201d李时珍《本草纲目》释其名曰：\u201c耆，长也。黄耆色黄，为补药之长。\u201d",b:"《神农本草经》《本草纲目》草部"},
 {n:"当归",f:"甘、辛，温 · 归肝、心、脾经",x:"表面黄棕色，断面黄白色、散布棕色油点（朱砂点），香气浓郁特异。",e:"补血活血、调经止痛、润肠通便，素有\u201c血中圣药\u201d之称。",s:"《本草纲目》：\u201c当归治头痛、心腹诸痛，润肠胃筋骨皮肤。\u201d古人取\u201c能使气血各有所归\u201d之义命名。",b:"《本草纲目》《千金方》"},
 {n:"枸杞子",f:"甘，平 · 归肝、肾经",x:"长卵形，表面红色至暗红、皱缩有光泽，顶端有小凸起花柱痕，味甘微酸。",e:"滋补肝肾、益精明目，为平补之剂，适合日常泡饮。",s:"《本草纲目》载：\u201c枸杞久服坚筋骨，轻身不老。\u201d陆游诗云\u201c雪霁茅堂钟磬清，晨斋枸杞一杯羹\u201d。",b:"《本草纲目》《随息居饮食谱》"},
 {n:"金银花",f:"甘，寒 · 归肺、心、胃经",x:"棒状花蕾，上粗下细、略弯曲，初开色白、后转金黄。",e:"清热解毒、疏散风热，为治一切内痈外痈之要药。",s:"《本草纲目》：\u201c忍冬久服轻身长年。\u201d花初开色白、后转黄，故名金银花。",b:"《本草纲目》《温病条辨》"},
 {n:"陈皮",f:"辛、苦，温 · 归脾、肺经",x:"成熟果皮，色橙红或红棕，外露油点，内面白色海绵状，质薄而软。",e:"理气健脾、燥湿化痰，\u201c陈久者良\u201d，广东新会陈皮最负盛名。",s:"《本草纲目》：\u201c橘皮，苦能泄能燥，辛能散，温能和。\u201d以\u201c陈\u201d字入名，取陈久之气不峻之理。",b:"《本草纲目》果部"},
 {n:"茯苓",f:"甘、淡，平 · 归心、脾、肾经",x:"不规则块片，外皮薄而粗糙呈棕褐色，切面白色细腻如粉，嚼之粘牙。",e:"利水渗湿、健脾宁心，四季可用，药性平和。",s:"《神农本草经》列为上品：\u201c主胸胁逆气……久服安魂养神。\u201d古人云\u201c千年之松，下有茯苓\u201d。",b:"《神农本草经》《本草纲目》"},
 {n:"甘草",f:"甘，平 · 归心、肺、脾、胃经",x:"外皮红棕色，断面纤维性、有裂隙，入口味甜而特殊。",e:"补脾益气、清热解毒、调和诸药，有\u201c国老\u201d之誉。",s:"《本草纲目》：\u201c甘草外赤中黄，色兼坤离……调和众药有功，故有国老之号。\u201d",b:"《神农本草经》《本草纲目》"},
 {n:"菊花",f:"甘、苦，微寒 · 归肺、肝经",x:"扁球状或团状的头状花序，舌状花瓣多而舒展，气清香。",e:"疏散风热、平肝明目、清热解毒，常与枸杞同泡以养目。",s:"《神农本草经》列为上品：\u201c主诸风头眩、肿痛……久服利血气，轻身耐老。\u201d",b:"《神农本草经》《随息居饮食谱》"},
 {n:"山楂",f:"酸、甘，微温 · 归脾、胃、肝经",x:"类球形，表面深红色、有细密皱纹和白色小斑点，果肉厚，味酸微甜。",e:"消食化积、行气散瘀，尤善消肉食油腻之积。",s:"《本草纲目》：\u201c化饮食，消肉积、癥瘕、痰饮痞满吞酸。\u201d糖葫芦即源自其消食之用。",b:"《本草纲目》果部"},
 {n:"生姜",f:"辛，微温 · 归肺、脾、胃经",x:"不规则块状、扁平有指状分枝，表面黄褐，断面浅黄、纤维明显，辛辣气浓。",e:"解表散寒、温中止呕、温肺止咳，有\u201c呕家圣药\u201d之称。",s:"《本草纲目》：\u201c姜辛而不荤，去邪辟恶……可蔬可和，可果可药。\u201d孔子\u201c不撤姜食\u201d，亦重其养生之功。",b:"《本草纲目》菜部"},
 {n:"人参",f:"甘、微苦，微温 · 归脾、肺、心经",x:"主根纺锤形，上端有芦头与密集芦碗，下部渐细有支根，断面淡黄白有菊花纹，香气特异。",e:"大补元气、复脉固脱、补脾益肺、生津安神，为补气第一要药。",s:"《神农本草经》列为上品：\u201c主补五脏，安精神……久服轻身延年。\u201d",b:"《神农本草经》《本草纲目》草部"},
 {n:"莲子",f:"甘、涩，平 · 归脾、肾、心经",x:"卵圆形，表面浅黄棕色，一端中心呈乳头状突起，去芯后味甘微涩。",e:"补脾止泻、益肾涩精、养心安神，是药食同源的代表。",s:"《本草纲目》：\u201c莲之味甘，气温而性啬……乃脾之果也。\u201d",b:"《本草纲目》《随息居饮食谱》"},
 {n:"山药",f:"甘，平 · 归脾、肺、肾经",x:"圆柱形，表面黄白光滑、有纵沟，断面洁白、富粉性。",e:"补脾养胃、生津益肺、补肾涩精，平补三焦，老幼皆宜。",s:"《本草纲目》薯蓣条：\u201c益肾气，健脾胃……久服耳目聪明，轻身不饥延年。\u201d",b:"《本草纲目》《随息居饮食谱》"},
 {n:"薄荷",f:"辛，凉 · 归肺、肝经",x:"茎方柱形、对叶皱缩，全体被柔毛，搓揉有特异清凉香气。",e:"疏散风热、清利头目、利咽透疹，其气清凉，为辛凉解表之品。",s:"《本草纲目》：\u201c薄荷辛能发散，凉能清利，专于消风散热。\u201d",b:"《本草纲目》草部"}
];
/* ===== 本草扩展名录：常用中药按功效分门别类 =====
   前 14 味（HERBS）配有工笔插画，用于图鉴 / 看图辨药 / 每日本草；
   本组只有文字条目，进入问答知识库、RAG 语料、竞赛题库与「本草名录」索引。
   cat 用于分类浏览，也是「有无插画」的标记：有 cat = 无图、不参与集章。 */
const MATERIA_EXTRA=[
 {n:"桂枝",f:"辛、甘，温 · 归心、肺、膀胱经",x:"圆柱形小段，外皮红棕至棕色，有细纵纹与皮孔，切面皮部红棕、木部黄白，香气特异。",e:"发汗解肌、温通经脉、助阳化气、平冲降气，为《伤寒论》桂枝汤之君药。",s:"《神农本草经》列「牡桂」为上品：主上气咳逆、利关节、补中益气。《伤寒论》以桂枝汤为群方之冠。",b:"《神农本草经》《伤寒论》《汤头歌诀》",cat:"解表"},
 {n:"防风",f:"辛、甘，微温 · 归膀胱、肝、脾经",x:"根呈长圆锥形，根头部有密集环纹（蚯蚓头），外皮灰棕色、粗糙，断面有裂隙，气微香。",e:"祛风解表、胜湿止痛、止痉，被誉为「风药中之润剂」，玉屏风散中用之固表。",s:"《神农本草经》列为上品：「主大风头眩痛，恶风，风邪目盲无所见。」",b:"《神农本草经》《本草纲目》",cat:"解表"},
 {n:"葛根",f:"甘、辛，凉 · 归脾、胃、肺经",x:"纵切的长方形厚片或小方块，外皮淡棕色，切面黄白色、纹理不明显，质韧、富粉性。",e:"解肌退热、生津止渴、透疹、升阳止泻，张仲景葛根汤治项背强痛。",s:"《神农本草经》列葛为上品：「主消渴，身大热，呕吐，诸痹，起阴气，解诸毒。」",b:"《神农本草经》《伤寒论》",cat:"解表"},
 {n:"石膏",f:"甘、辛，大寒 · 归肺、胃经",x:"纤维状集合体，呈长块状或不规则形，白色至灰白，纵断面具绢丝样光泽，质松易碎。",e:"清热泻火、除烦止渴，为清阳明气分实热之要药，白虎汤以此为主。",s:"《神农本草经》列为中品：「主中风寒热，心下逆气惊喘，口干舌焦不能息。」",b:"《神农本草经》《伤寒论》",cat:"清热"},
 {n:"黄芩",f:"苦，寒 · 归肺、胆、脾、大肠、小肠经",x:"圆锥形根，表面棕黄或深黄、有扭曲纵皱，断面黄色、中心红棕，老根中空者称「枯芩」。",e:"清热燥湿、泻火解毒、止血、安胎，善清上焦肺热，小柴胡汤中用之。",s:"《神农本草经》列为中品：「主诸热黄疸，肠澼泄痢，逐水，下血闭。」",b:"《神农本草经》《伤寒论》",cat:"清热"},
 {n:"黄连",f:"苦，寒 · 归心、脾、胃、肝、胆、大肠经",x:"根茎多分枝、形如鸡爪，表面灰黄或黄褐、粗糙，断面皮部橙红、木部鲜黄，味极苦。",e:"清热燥湿、泻火解毒，善清心胃之火，有「哑巴吃黄连，有苦说不出」之谚。",s:"《神农本草经》列为上品：「主热气目痛，眦伤泣出，明目，肠澼腹痛下痢。」",b:"《神农本草经》《本草纲目》",cat:"清热"},
 {n:"生地黄",f:"甘，寒 · 归心、肝、肾经",x:"不规则团块或长圆形，表面棕黑或棕灰、极皱缩，断面棕黑或乌黑、有光泽，质柔润黏腻。",e:"清热凉血、养阴生津，与蒸制后的熟地黄功效有别：生用凉血、熟用补血。",s:"《神农本草经》列「干地黄」为上品：「主折跌绝筋，伤中，逐血痹，填骨髓，长肌肉。」",b:"《神农本草经》《本草纲目》",cat:"清热"},
 {n:"苍术",f:"辛、苦，温 · 归脾、胃、肝经",x:"不规则连珠状或结节状圆柱形，表面灰棕色，断面黄白色、散有橙黄色油室，暴露日久可起白霜。",e:"燥湿健脾、祛风散寒、明目，与白术一燥一补，为治湿滞中焦之要药。",s:"《神农本草经》列「术」为上品：「主风寒湿痹，死肌，痉，疸，止汗，除热，消食。」",b:"《神农本草经》《本草纲目》",cat:"祛湿"},
 {n:"薏苡仁",f:"甘、淡，凉 · 归脾、胃、肺经",x:"宽卵形或长椭圆形，表面乳白色、光滑，背面圆凸、腹面有较宽而深的纵沟，质坚实。",e:"利水渗湿、健脾止泻、除痹排脓、解毒散结，药食两宜，常入粥食。",s:"《神农本草经》列为上品：「主筋急拘挛不可屈伸，风湿痹，下气，久服轻身益气。」",b:"《神农本草经》《随息居饮食谱》",cat:"祛湿"},
 {n:"泽泻",f:"甘、淡，寒 · 归肾、膀胱经",x:"类球形或椭圆形，表面黄白或淡黄棕、有不规则横向环状浅沟纹，断面黄白、粉性。",e:"利水渗湿、泄热，六味地黄丸「三泻」之一，与熟地黄相配利水而不伤阴。",s:"《神农本草经》列为上品：「主风寒湿痹，乳难，消水，养五脏，益气力，肥健。」",b:"《神农本草经》《小儿药证直诀》",cat:"祛湿"},
 {n:"干姜",f:"辛，热 · 归脾、胃、肾、心、肺经",x:"扁平不规则块状，具指状分枝，表面灰黄或浅灰棕、粗糙，断面黄白或灰白、显粉性与纤维。",e:"温中散寒、回阳通脉、温肺化饮，与生姜同出一物：生姜走表，干姜守中。",s:"《神农本草经》列为中品：「主胸满咳逆上气，温中止血，出汗，逐风湿痹。」",b:"《神农本草经》《伤寒论》",cat:"温里"},
 {n:"肉桂",f:"辛、甘，大热 · 归肾、脾、心、肝经",x:"槽状或卷筒状厚片，外表面灰棕色、有细皱纹，内表面红棕、油润，划之显油痕，气香浓烈。",e:"补火助阳、引火归元、散寒止痛、温通经脉，为温补肾阳之要药。",s:"《神农本草经》列「牡桂」「菌桂」为上品，主利关节、补中益气；《本草纲目》详辨桂之数种。",b:"《神农本草经》《本草纲目》",cat:"温里"},
 {n:"白术",f:"苦、甘，温 · 归脾、胃经",x:"不规则肥厚团块，表面灰黄或灰棕、有瘤状突起，断面黄白、有棕黄色油室，烘干者色较深。",e:"健脾益气、燥湿利水、止汗、安胎，四君子汤中与人参、茯苓、甘草同用。",s:"《神农本草经》列「术」为上品；《本草纲目》谓其「健脾强胃，进食，和中，消痰」。",b:"《神农本草经》《汤头歌诀》",cat:"补益"},
 {n:"党参",f:"甘，平 · 归脾、肺经",x:"长圆柱形、稍弯曲，表面灰黄至黄棕，根头有多数疣状突起（狮子盘头），断面有放射状纹理。",e:"健脾益肺、养血生津，常作人参之平补代用品，适合日常调养。",s:"《本草从新》《本草纲目拾遗》始载，谓其「补中益气，和脾胃，除烦渴」。",b:"《本草从新》《本草纲目拾遗》",cat:"补益"},
 {n:"熟地黄",f:"甘，微温 · 归肝、肾经",x:"不规则团块，内外皆乌黑发亮、质柔润而黏，味甜，系生地黄经酒炖或蒸制而成。",e:"补血滋阴、益精填髓，六味地黄丸之君药，与生地黄凉血之功相对。",s:"《本草纲目》载地黄「生则大寒而凉血，熟则微温而补肾」，炮制改药性之典型。",b:"《本草纲目》《小儿药证直诀》",cat:"补益"},
 {n:"麦冬",f:"甘、微苦，微寒 · 归心、肺、胃经",x:"纺锤形小块根，表面淡黄白、有细纵纹，质柔韧，断面黄白色、半透明，中柱细小，味甘微苦。",e:"养阴润肺、益胃生津、清心除烦，沙参麦冬汤、生脉饮皆用之。",s:"《神农本草经》列为上品：「主心腹结气，伤中伤饱，胃络脉绝，羸瘦短气。」",b:"《神农本草经》《温病条辨》",cat:"补益"},
 {n:"香附",f:"辛、微苦、微甘，平 · 归肝、脾、三焦经",x:"纺锤形，表面棕褐或黑褐、有纵皱纹与环节，质硬，蒸煮后断面红棕、角质样，气香。",e:"疏肝解郁、理气宽中、调经止痛，被誉为「气病之总司、女科之主帅」。",s:"《本草纲目》谓其「利三焦，解六郁，消饮食积聚、痰饮痞满」，为理气第一品。",b:"《本草纲目》《汤头歌诀》",cat:"理气"},
 {n:"木香",f:"辛、苦，温 · 归脾、胃、大肠、三焦、胆经",x:"圆柱形或半圆柱形，表面黄棕至灰褐、有明显纵沟与侧根痕，断面灰褐、有放射状纹理，气芳香浓烈。",e:"行气止痛、健脾消食，善行中下焦气滞，与黄连相配即香连丸。",s:"《神农本草经》列为上品：「主邪气，辟毒疫温鬼，强志，主淋露。」",b:"《神农本草经》《本草纲目》",cat:"理气"},
 {n:"川芎",f:"辛，温 · 归肝、胆、心包经",x:"不规则结节状拳形团块，表面黄褐、粗糙皱缩，断面黄白、散有黄棕色小油点，香气浓郁。",e:"活血行气、祛风止痛，为「血中之气药」，四物汤中用之使补而不滞。",s:"《神农本草经》列「芎穷」为中品：「主中风入脑头痛，寒痹筋挛缓急，金创，妇人血闭无子。」",b:"《神农本草经》《太平惠民和剂局方》",cat:"活血"},
 {n:"丹参",f:"苦，微寒 · 归心、肝经",x:"根茎短粗、顶端残留茎基，根数条呈长圆柱形，表面砖红或暗红棕、有纵皱，断面皮部棕红、木部灰黄。",e:"活血祛瘀、通经止痛、清心除烦、凉血消痈，有「一味丹参，功同四物」之说。",s:"《神农本草经》列为上品：「主心腹邪气，肠鸣幽幽如走水，寒热积聚，破癥除瘕。」",b:"《神农本草经》《本草纲目》",cat:"活血"},
 {n:"三七",f:"甘、微苦，温 · 归肝、胃经",x:"类圆锥形或圆柱形，表面灰褐或灰黄、有断续纵皱与支根痕，顶端有茎痕，质坚实、击碎后皮木易分离。",e:"散瘀止血、消肿定痛，止血而不留瘀，云南白药之主药。",s:"《本草纲目》载「三七」：此药近时始出，南人军中用为金疮要药，云有奇功。",b:"《本草纲目》",cat:"活血"},
 {n:"半夏",f:"辛，温；有毒 · 归脾、胃、肺经",x:"类球形，表面白色或浅黄、顶端有凹陷茎痕，周围密布麻点状根痕，质坚实，断面洁白、富粉性。",e:"燥湿化痰、降逆止呕、消痞散结；生品有毒，须经姜、矾等炮制后入药。",s:"《神农本草经》列「半夏」为下品：「主伤寒寒热，心下坚，下气，喉咽肿痛，头眩胸胀。」",b:"《神农本草经》《伤寒论》",cat:"化痰"},
 {n:"桔梗",f:"苦、辛，平 · 归肺经",x:"圆柱形或略呈纺锤形，表面淡黄白至黄色、有扭转纵沟，质脆，断面皮部黄白、木部淡黄（金井玉栏）。",e:"宣肺、利咽、祛痰、排脓，为舟楫之剂，能载药上行入肺。",s:"《神农本草经》列为下品：「主胸胁痛如刀刺，腹满肠鸣幽幽，惊恐悸气。」",b:"《神农本草经》《伤寒论》",cat:"化痰"},
 {n:"酸枣仁",f:"甘、酸，平 · 归肝、胆、心经",x:"扁圆形或扁椭圆形，表面紫红或紫褐、平滑有光泽，一面中央有微隆起的纵线纹，种皮较脆。",e:"养心补肝、宁心安神、敛汗、生津，为治虚烦不眠之要药。",s:"《神农本草经》列为上品：「主心腹寒热，邪结气聚，四肢酸疼湿痹，久服安五脏。」",b:"《神农本草经》《金匮要略》",cat:"安神"},
 {n:"五味子",f:"酸、甘，温 · 归肺、心、肾经",x:"不规则球形或扁球形，表面红色、紫红或暗红、皱缩显油润，果肉柔软，种子肾形、有光泽。",e:"收敛固涩、益气生津、补肾宁心，五味俱全故名，生脉饮中与人参、麦冬同用。",s:"《神农本草经》列为上品：「主益气，咳逆上气，劳伤羸瘦，补不足，强阴，益男子精。」",b:"《神农本草经》《伤寒论》讲义",cat:"安神"},
 {n:"大黄",f:"苦，寒 · 归脾、胃、大肠、肝、心包经",x:"类圆柱形、圆锥形或不规则块片，表面黄棕至红棕，断面淡红棕或黄棕、显颗粒性，髓部有星点环列。",e:"泻下攻积、清热泻火、凉血解毒、逐瘀通经，有「将军」之号，生用泻下力强。",s:"《神农本草经》列为下品：「主下瘀血，血闭寒热，破癥瘕积聚，留饮宿食，荡涤肠胃。」",b:"《神农本草经》《伤寒论》",cat:"泻下"}
];
const ALL_HERBS=HERBS.concat(MATERIA_EXTRA);           // 全站知识口径：40 味（14 味有插画 / 26 味文字条目）
const HERB_CATS=["解表","清热","祛湿","温里","补益","理气","活血","化痰","安神","泻下"];
const FORMULAS=[
 {n:"四君子汤",s:"《太平惠民和剂局方》",comp:"人参（或党参）、白术、茯苓、炙甘草",d:"益气健脾。主治脾胃气虚证——面色萎白、语声低微、食少便溏、气短乏力。四味皆平和之品，取\u201c君子致中和\u201d之义，为补气剂的基础方，后世诸多补气健脾方多从此化裁。",b:"《太平惠民和剂局方》《汤头歌诀》"},
 {n:"四物汤",s:"始载唐·蔺道人《仙授理伤续断秘方》，后广收《太平惠民和剂局方》",comp:"熟地黄、当归、白芍、川芎",d:"补血调血。主治营血虚滞证——心悸失眠、头晕目眩、面色无华、月经不调或经闭不行。四味补中有行、静中有动，为妇科调经与补血的第一基础方，与四君子汤并称气血双补之基。",b:"《太平惠民和剂局方》《汤头歌诀》"},
 {n:"八珍汤",s:"明·薛己《正体类要》",comp:"人参、白术、茯苓、甘草、熟地黄、当归、白芍、川芎（四君子汤合四物汤）",d:"气血双补。主治气血两虚证——面色苍白或萎黄、气短乏力、头晕心悸、食少懒言。四君补气、四物补血，合而用之，气旺则生血、血足则载气。",b:"《正体类要》《汤头歌诀》"},
 {n:"六味地黄丸",s:"宋·钱乙《小儿药证直诀》",comp:"熟地黄、山萸肉、山药、泽泻、牡丹皮、茯苓",d:"滋阴补肾。三补（熟地、山萸、山药）三泻（泽泻、丹皮、茯苓），补而不滞。原为儿科\u201c地黄丸\u201d，后世广泛用于肾阴亏虚之证，如腰膝酸软、头晕耳鸣、盗汗遗精。",b:"《小儿药证直诀》《汤头歌诀》"},
 {n:"桂枝汤",s:"汉·张仲景《伤寒论》",comp:"桂枝、芍药、生姜、大枣、炙甘草",d:"解肌发表、调和营卫。被誉为\u201c群方之冠\u201d，主治太阳中风表虚证——发热恶风、汗出、脉浮缓。方后嘱\u201c啜热稀粥以助药力\u201d，体现仲景护胃气、助正气的巧思。",b:"《伤寒论》《汤头歌诀》"},
 {n:"小柴胡汤",s:"汉·张仲景《伤寒论》",comp:"柴胡、黄芩、半夏、生姜、人参、大枣、炙甘草",d:"和解少阳。主治少阳病——往来寒热、胸胁苦满、默默不欲饮食、心烦喜呕。为和解剂之代表方，凡半表半里、枢机不利者多用之，亦是\u201c和法\u201d的典范。",b:"《伤寒论》《汤头歌诀》"},
 {n:"逍遥散",s:"《太平惠民和剂局方》",comp:"柴胡、当归、白芍、白术、茯苓、炙甘草、薄荷、生姜",d:"疏肝解郁、养血健脾。主治肝郁血虚脾弱证——两胁作痛、头痛目眩、神疲食少、月经不调。方名\u201c逍遥\u201d，谓肝郁得疏、血虚得养则身心逍遥，为调和肝脾的名方。",b:"《太平惠民和剂局方》《汤头歌诀》"},
 {n:"玉屏风散",s:"《医方类聚》引《世医得效方》",comp:"黄芪、白术、防风",d:"益气固表止汗。三味如御风之屏障，故名\u201c玉屏风\u201d。主治表虚不固、自汗恶风、易感风邪者，是体虚易感冒者的经典防护方。",b:"《世医得效方》《汤头歌诀》"},
 {n:"藿香正气散",s:"《太平惠民和剂局方》",comp:"藿香、紫苏、白芷、大腹皮、茯苓、白术、陈皮、半夏曲、厚朴、桔梗、炙甘草（生姜、大枣为引）",d:"解表化湿、理气和中。主治外感风寒、内伤湿滞——恶寒发热、头痛、胸膈满闷、脘腹胀痛、呕吐泄泻，为夏月感寒伤湿、脾胃不和之常用方。",b:"《太平惠民和剂局方》《汤头歌诀》"},
 {n:"补中益气汤",s:"金元·李东垣《脾胃论》",comp:"黄芪、白术、陈皮、升麻、柴胡、人参、炙甘草、当归",d:"补中益气、升阳举陷。主治脾虚气陷证——体倦乏力、食少腹胀、久泻久痢、脏器下垂（如胃下垂、脱肛）。东垣\u201c内伤脾胃，百病由生\u201d之说的代表方。",b:"《脾胃论》《汤头歌诀》"},
 {n:"归脾汤",s:"宋·严用和《济生方》（明·薛己加味）",comp:"白术、茯神、黄芪、龙眼肉、酸枣仁、人参、木香、炙甘草、当归、远志、生姜、大枣",d:"益气补血、健脾养心。主治心脾两虚、气血不足——心悸怔忡、失眠健忘、食少体倦、面色萎黄、月经不调或崩漏。补血而不滞气，健脾而不碍运。",b:"《济生方》《汤头歌诀》"},
 {n:"龙胆泻肝汤",s:"清·汪昂《医方集解》（同名方本于《太平惠民和剂局方》加味）",comp:"龙胆草、黄芩、栀子、泽泻、木通、车前子、当归、生地黄、柴胡、炙甘草",d:"清泻肝胆实火、清利肝胆湿热。主治肝胆火旺、湿热下注——胁痛口苦、耳聋耳肿、小便淋浊、阴痒带下、舌红苔黄。泻中有补、利中有滋，防苦寒伤阴。",b:"《医方集解》《汤头歌诀》"},
 {n:"二陈汤",s:"《太平惠民和剂局方》",comp:"半夏、陈皮、茯苓、炙甘草（生姜、乌梅为引）",d:"燥湿化痰、理气和中。为化痰基础方——主治湿痰证，咳嗽痰多、色白易咯、恶心呕吐、胸膈痞闷、舌苔白腻。方中半夏、陈皮以陈久者良，故名\u201c二陈\u201d。",b:"《太平惠民和剂局方》《汤头歌诀》"},
 {n:"血府逐瘀汤",s:"清·王清任《医林改错》",comp:"桃仁、红花、当归、生地黄、川芎、赤芍、牛膝、桔梗、柴胡、枳壳、炙甘草",d:"活血化瘀、行气止痛。主治胸中血瘀证——胸痛、头痛日久不愈、痛如针刺而有定处、心悸失眠、入暮潮热。王清任\u201c活血化瘀\u201d诸方之代表，尤擅胸胁血瘀。",b:"《医林改错》《汤头歌诀》"},
 {n:"肾气丸（金匮肾气丸）",s:"汉·张仲景《金匮要略》",comp:"干地黄、山药、山萸肉、泽泻、茯苓、牡丹皮、桂枝、附子（后世又称\u201c桂附地黄丸\u201d）",d:"温补肾阳、化气行水。主治肾阳不足——腰痛脚软、畏寒肢冷、小便不利或反多、阳痿早泄、痰饮水肿。阴中求阳、少火生气，为温补肾阳的祖方。",b:"《金匮要略》《汤头歌诀》"}
];
const ACUP=[
 {n:"足三里",m:"足阳明胃经",loc:"小腿外侧，犊鼻（外膝眼）下3寸，胫骨前缘外一横指处",d:"胃经合穴，\u201c肚腹三里留\u201d。健脾和胃、扶正培元、通经活络，为最常用的保健要穴。民间有\u201c常灸足三里，胜吃老母鸡\u201d之谚，常灸可增强体质。",b:"《针灸大成》《黄帝内经》"},
 {n:"涌泉",m:"足少阴肾经",loc:"足底前1/3凹陷处（屈足卷趾时足心最凹处），约当第2、3趾趾缝纹头端与足跟连线的前1/3与后2/3交点",d:"肾经井穴。肾经之气如源泉之水涌出足下，故名。引火归元、滋阴降火、宁神开窍，睡前按揉或艾灸可助眠安神、引虚火下行。",b:"《针灸大成》《黄帝内经》"},
 {n:"合谷",m:"手阳明大肠经",loc:"手背第1、2掌骨之间，约平第2掌骨桡侧中点（拇、食指并拢时肌肉隆起最高处）",d:"大肠经原穴，\u201c面口合谷收\u201d。镇静止痛、通经活络、解表清热，头面部病症（牙痛、头痛、面瘫）与解表发汗常用要穴。孕妇慎用。",b:"《针灸大成》"},
 {n:"百会",m:"督脉",loc:"头顶正中，两耳尖连线的中点处",d:"督脉要穴，居一身之巅，为诸阳之会。醒脑开窍、升阳举陷、安神定志，常用于头晕目眩、健忘、耳鸣及脏器下垂（如脱肛、子宫脱垂）。",b:"《针灸大成》《黄帝内经》"},
 {n:"关元",m:"任脉",loc:"下腹部前正中线上，脐下3寸",d:"小肠之募穴，为元气之根、\u201c男子藏精、女子蓄血\u201d之处。培元固本、温肾壮阳、补益下焦，为保健灸常用穴，尤宜阳虚畏寒、元气不足者。",b:"《针灸大成》《黄帝内经》"},
 {n:"气海",m:"任脉",loc:"下腹部前正中线上，脐下1.5寸",d:"补气要穴，被称为\u201c元气之海\u201d。益气助阳、调理气机，主治气虚乏力、腹痛虚劳，常与关元相配以补益下焦元气。",b:"《针灸大成》"},
 {n:"内关",m:"手厥阴心包经",loc:"前臂掌侧，腕横纹上2寸，掌长肌腱与桡侧腕屈肌腱之间",d:"心包经络穴、八脉交会穴（通阴维脉）。宁心安神、理气止痛、和胃降逆，常用于心悸、胸闷、晕车呕吐、胃痛，亦是\u201c四关\u201d配穴之一。",b:"《针灸大成》"},
 {n:"三阴交",m:"足太阴脾经",loc:"小腿内侧，内踝尖上3寸，胫骨内侧缘后方",d:"脾、肝、肾三条阴经的交会穴。健脾益血、调肝补肾、调经止带，为妇科第一要穴，月经不调、带下、失眠、脾胃虚弱多用。孕妇禁针。",b:"《针灸大成》《黄帝内经》"},
 {n:"委中",m:"足太阳膀胱经",loc:"腘横纹中点（膝后窝中央）",d:"膀胱经合穴，\u201c腰背委中求\u201d。舒筋通络、凉血泄热，腰背疼痛、下肢痿痹及急性腰扭伤常用，刺络放血亦取其清热。",b:"《针灸大成》"},
 {n:"列缺",m:"手太阴肺经",loc:"前臂桡侧缘，腕横纹上1.5寸，肱桡肌腱与拇长展肌腱之间",d:"肺经络穴、八脉交会穴（通任脉）。\u201c头项寻列缺\u201d，疏风解表、宣肺利咽、通调任脉，头痛项强、咳嗽咽喉肿痛常用。",b:"《针灸大成》"},
 {n:"风池",m:"足少阳胆经",loc:"项后枕骨之下，胸锁乳突肌与斜方肌上端之间的凹陷处（平风府穴）",d:"祛风解表、清头明目、通利官窍。感冒头痛、眩晕、目赤肿痛、鼻塞多用，亦是治风之要穴，外感与内风皆宜。",b:"《针灸大成》"},
 {n:"太冲",m:"足厥阴肝经",loc:"足背第1、2跖骨间，跖骨底结合部前方凹陷中（足背动脉搏动处）",d:"肝经原穴、输穴。平肝息风、疏肝理气、清肝明目，为调畅情志第一要穴，与合谷并称\u201c四关\u201d，头痛眩晕、月经不调、急躁易怒多用。",b:"《针灸大成》"}
];
const TOPICS=[
 {n:"上火",d:"中医认为\u201c上火\u201d多因阴阳失衡、内火炽盛，可分为实火与虚火：实火者面红目赤、口舌生疮、小便短赤，宜清热泻火，可饮金银花、菊花茶；虚火者午后潮热、口干咽燥，宜滋阴降火，可酌用麦冬、石斛。《本草纲目》云\u201c去火除烦，莫过于水\u201d，调畅情志、忌辛辣烧烤亦是要诀。",b:"《本草纲目》《温病条辨》",k:["口舌生疮","实火","虚火","火气"]},
 {n:"湿气",d:"湿为阴邪，易困脾胃。舌苔白厚腻、身体困重、大便黏滞者多为痰湿。祛湿三法：健脾（山药、茯苓煮粥）、行气（陈皮泡水）、动养（微汗运动）。古人云\u201c千寒易除，一湿难去\u201d，贵在持之以恒。",b:"《本草纲目》《随息居饮食谱》",k:["祛湿","湿气重"]},
 {n:"中医体质",d:"中医体质学说将人分为平和、气虚、阳虚、阴虚、痰湿、湿热、血瘀、气郁、特禀九种体质，其思想可上溯至《黄帝内经》\u201c阴阳二十五人\u201d篇。体质决定易感疾病与养生方向，辨清体质，方能因人施养。",b:"《黄帝内经》",k:["九种体质","体质是什么"]},
 {n:"药食同源",d:"\u201c药食同源\u201d指许多食物兼具药物之性：生姜、山药、莲子、山楂、枸杞、菊花皆在其列。《黄帝内经》云\u201c五谷为养，五果为助，五畜为益，五菜为充\u201d，饮食调养首重五谷与四时。",b:"《黄帝内经》《随息居饮食谱》",k:["食疗","食补"]},
 {n:"熬夜",d:"《黄帝内经》云：\u201c阳气尽则卧，阴气尽则寤。\u201d子时（23点—1点）胆经当令、丑时肝经当令，此时不眠则肝胆不得休养，易致阴虚火旺、面色晦暗。养生第一课，即在\u201c起居有常，不妄作劳\u201d。",b:"《黄帝内经》",k:["失眠","睡不好","晚睡","睡不着","入睡困难","多梦","睡眠"]},
 {n:"养生",d:"说白了就四句话：<b>跟着季节过日子、吃饭七分饱、晚上别熬夜、心情别内耗</b>。《黄帝内经》十六字总纲「法于阴阳，和于术数，食饮有节，起居有常」，翻成大白话：顺应四季变化，找适合自己的锻炼方式，三餐规律别暴食，作息稳定少熬夜。做到这四条，比多数保健品都管用。想看某个季节具体怎么养？直接问「春天怎么养生」这类问题，药童给你按季拆解〜",b:"《黄帝内经》《千金方》",k:["保健","怎么养生"]},
 {n:"感冒",d:"感冒先别急着灌药！中医把感冒分成两路：风寒感冒——怕冷重、流清鼻涕，来碗生姜红糖水，捂被子发发汗，把寒气请出去；风热感冒——喉咙痛、流黄鼻涕，金银花、菊花茶安排上，清热又利咽。《伤寒论》里的桂枝汤就是治感冒的祖师爷方子。不过要是高烧不退，别跟本药童犟，赶紧去医院！",b:"《伤寒论》《温病条辨》",k:["风寒感冒","风热感冒","流鼻涕","着凉","伤风"]},
 {n:"咳嗽",d:"咳嗽也分性格：寒咳痰白稀，烤个橘子或炖点冰糖雪梨加片姜；热咳痰黄稠，雪梨炖冰糖，薄荷利咽也不错。老祖宗说\u201c五脏六腑皆令人咳\u201d——咳超过两周还没好，请放下手机直奔医院，这题药童不背锅〜",b:"《本草纲目》《伤寒论》",k:["止咳","痰多","嗓子痒","喉咙不舒服"]},
 {n:"便秘",d:"嗯…这个话题有味道但很重要！中医看便秘：肠燥型多吃润物——黑芝麻、核桃、蜂蜜水；气虚型推动无力——补气才管用，黄芪、山药安排上；上火型少吃辣多喝水。再送一招祖传秘方：早上空腹温水一杯 + 顺时针揉腹一百下 + 别带手机进厕所〜",b:"《本草纲目》《随息居饮食谱》",k:["排便","拉不出","大便干","消化不好"]},
 {n:"痛经",d:"姑娘们看过来！中医认为\u201c不通则痛，不荣则痛\u201d：受凉型喝点红糖姜茶、热水袋敷肚子，当归生姜羊肉汤是暖宫名膳；气滞型经前胀痛，玫瑰花茶疏疏肝。经期忌生冷、忌熬夜、忌生气（说的就是你，跟人吵架那次）。痛到打滚请及时就医，别硬扛！",b:"《本草纲目》《伤寒论》",k:["月经","例假","姨妈痛","经期"]},
 {n:"减肥",d:"本药童掐指一算，问这题的朋友最多！中医看肥胖多与痰湿有关——茯苓、陈皮、山楂是祛湿消积三剑客；荷叶茶、冬瓜汤也是刮油好手。但！是！《内经》说\u201c起居有常，不妄作劳\u201d，管住嘴迈开腿才是正道；减肥药和纯饿肚子这种歪门邪道，药童摇头拒绝〜",b:"《本草纲目》《随息居饮食谱》",k:["瘦身","刮油","减脂","瘦","体重"]},
 {n:"痘痘",d:"脸上的痘，是身体写的吐槽信！额头痘多为心火旺——少熬夜，菊花、金银花茶降降火；口周痘多脾胃湿热——火锅奶茶先停一停（药童知道这很难）；下巴痘注意规律作息。记住：挤痘一时爽，痘坑火葬场。反复爆痘严重请找皮肤科大夫把把脉〜",b:"《本草纲目》《温病条辨》",k:["痤疮","粉刺","长痘","冒痘"]},
 {n:"口臭",d:"开口跪的尴尬，中医有解！多数口臭源于胃火或积食：山楂消食、陈皮理气、薄荷清新口气，饭后含两片；晚餐七分饱、少辛辣烧烤。若长期口臭还伴反酸，建议查查幽门螺杆菌——这题超纲了，交给现代医学兄台！",b:"《本草纲目》《随息居饮食谱》",k:["口气","口气重","口气清新"]},
 {n:"贫血",d:"脸色苍白、蹲下起身眼冒金星？中医叫血虚！食补三宝：红枣、桂圆、猪肝；当归更是\u201c血中圣药\u201d，当归生姜羊肉汤是医圣张仲景的暖身名方。划重点：贫血原因很多（缺铁、地贫……），先验血查明原因，食补才补对方向哦〜",b:"《本草纲目》《伤寒论》",k:["血虚","补血","脸色苍白","头晕"]},
 {n:"手脚冰凉",d:"空调房里裹毯子的朋友请集合！这多是阳虚或气血不畅：生姜、当归入膳温温阳；睡前热水泡脚15分钟，泡到微微出汗即可，再按按涌泉穴引火归元；白天多动动，让气血跑起来。药童口诀：秋裤不是时尚敌人，是养生战袍！",b:"《伤寒论》《针灸大成》",k:["怕冷","手脚冷","体寒","暖不起来"]},
 {n:"疲劳",d:"明明睡了8小时还是累成电量1%？中医的\u201c虚\u201d分好几种：干活就喘、说话没劲多半是气虚——黄芪、山药、莲子煮粥；睡再多还困、舌边有齿痕多半是脾虚湿重——陈皮、茯苓安排；心烦手心热睡不好是阴虚——枸杞、麦冬泡水。对号入座，或去「体质辨识」做个小测试，两分钟锁定你的虚法〜",b:"《黄帝内经》《神农本草经》",k:["乏力","累","没精神","疲惫","提不起劲","犯困"]},
 {n:"脱发",d:"梳子上缠绕的头发，是青春流逝的证物（并不是）！中医看脱发：血虚风燥——发干枯易断，红枣、桑葚、黑芝麻补起来；肾精不足——发少枯黄，黑豆、核桃、枸杞是经典组合；压力型斑秃——先松口气再谈生发，玫瑰花茶疏疏肝。另附防脱守则：扎马尾别勒太紧、熬夜是头发头号杀手。脱落严重且成块，请去皮肤科报到〜",b:"《本草纲目》《千金方》",k:["掉头发","掉发","发际线","白发","生发"]},
 {n:"脾胃",d:"脾胃是人体的\u201c后勤部\u201d，中医叫\u201c后天之本\u201d！胃胀、没胃口、吃两口就饱——多半是脾胃虚弱：山药小米粥是养胃黄金档，陈皮山楂水消食导滞；贪凉饮冷伤脾阳，冰奶茶是隐形刺客（药童盯着你呢）。规律三餐比任何养胃偏方都灵：七分饱、细嚼慢咽、少吃生冷。长期胃痛、黑便请立刻就医，这不是食补能解决的战场〜",b:"《黄帝内经》《随息居饮食谱》",k:["胃疼","胃痛","胃胀","胃不好","消化不良","积食","胃口差","养胃"]},
 {n:"口腔溃疡",d:"嘴一破，吃饭说话都成了酷刑！中医叫\u201c口疮\u201d：心脾积热型——溃疡红肿疼得跳脚，淡竹叶、莲子心泡水清清火，西瓜霜喷剂也能救急；阴虚火旺型——反复发作、此起彼伏，麦冬、石斛滋阴。通用守则：辛辣烧烤先戒三天，B族维生素和锌也补上。超过两周不愈合的溃疡要重视，请口腔科医生看看才算数〜",b:"《本草纲目》《温病条辨》",k:["口腔溃疡","嘴破","口疮","舌头起泡","嘴里长泡"]},
 {n:"情绪",d:"心情不好也算病？中医早说了：\u201c百病生于气\u201d！思虑过度伤脾，焦虑日久化火，郁结于肝则胸闷叹气。药童情绪急救包：①玫瑰花、合欢花茶疏肝解郁；②八段锦、散步等温和运动把郁气\u201c动\u201d出去；③按揉膻中穴（两乳连线中点），闷气打结就揉它。但请记住：持续情绪低落超过两周，请认真对待，找专业心理医生聊聊——药童会讲笑话，但不会替代治疗〜",b:"《黄帝内经》《千金方》",k:["焦虑","压力大","心烦","emo","内耗","心情不好","情绪低落","郁闷"]},
 {n:"免疫力",d:"别人打喷嚏你中枪，流感季回回不落？中医叫\u201c卫气不固\u201d——身体的防护罩漏风了！补卫气三件套：黄芪泡水（中医界的\u201c免疫模范生\u201d）、玉屏风散（防风+黄芪+白术，名字起得很直白：像屏风一样挡住外邪）、规律作息。再加两条：均衡饮食别节食、适度运动微出汗。注意：真生病了该看医生看医生，免疫力是日常功课，不是速效救心丸〜",b:"《黄帝内经》《神农本草经》",k:["免疫力","抵抗力","容易感冒","体质差","总生病"]},
 {n:"嗓子疼",d:"吞口水像吞刀片？中医看咽痛也分寒热：风热型——咽红肿痛、口干，金银花、薄荷、胖大海泡水，清热利咽；风寒型——咽痒不红、恶寒，姜汤驱寒为主，别急着灌凉茶。教师、主播等用嗓大户常备麦冬石斛茶。护嗓冷知识：少清嗓子（越清越伤）、说话省着点用。若嘶哑超过两周或呼吸困难，直奔耳鼻喉科，别拖〜",b:"《温病条辨》《本草纲目》",k:["喉咙痛","咽喉肿痛","嗓子哑","咽炎","扁桃体","吞刀片"]},
 {n:"八段锦",d:"想养生又没装备？老祖宗早给你备好了\u201c居家健身操\u201d！八段锦——八式动作软如绸，宋朝人就在练，「双手托天理三焦」一式拉开，筋骨全开；五禽戏——华佗发明的模仿秀，虎鹿熊猿鸟各演一遍；太极拳——慢动作里藏内功。晨起 15 分钟，微微出汗即可，比赖床刷手机强多了。附赠口号：练完八段锦，上班不腰疼（药童亲测，骗人是小狗）〜",b:"《千金方》《黄帝内经》",k:["八段锦","太极","五禽戏","站桩","气功","传统运动","健身气功"]},
 {n:"中暑",d:"三伏天的头号反派！轻度中暑——头晕恶心大汗，速速转移到阴凉处，补水补盐，藿香正气水是居家常备（注意：别和头孢同服，会出大事）；重度中暑——高烧不出汗、意识模糊，这是会要命的急症，立刻打 120，别犹豫！预防口诀：避开正午毒日头、遮阳帽人手一顶、少量多次喝水。老弱孕产人群高温天请尽量宅在阴凉处〜",b:"《温病条辨》《千金方》",k:["中暑","藿香正气","暑气","天太热","热射病"]},
 {n:"本草",d:"好问题，这可是本店招牌的\u201c本\u201d字来源！\u201c本草\u201d是古代对中药的统称——因药物中草木类占绝大多数，\u201c本\u201d取根本本源之意，故称\u201c本草\u201d。现存最早药物学专著是汉代《神农本草经》（收药365味），巅峰之作是明代李时珍《本草纲目》（收药1892种）。历代研究中药的学问就叫\u201c本草学\u201d。本药童肚里的黄芪、当归、枸杞，都是正儿八经的本草出身哦〜",b:"《神农本草经》《本草纲目》",k:["什么是本草","本草是什么","中药是什么","中医药是什么"]}
];
/* ===== 相似药材外观辨别：长得像不难认，看懂要点一眼分清 ===== */
const LOOKALIKES=[
 {a:"金银花",b:"菊花",sA:"棒状花蕾，上粗下细、略弯曲，初开色白、后转金黄",sB:"扁球状或团状的头状花序，舌状花瓣多而舒展",tip:"金银花是<b>棒状花蕾</b>：上粗下细、略弯曲，初开色白如银、后转金黄，故得名「金银」；菊花则是<b>扁球状团花</b>：舌状花瓣多而舒展，气清香。一句话：一个是「小棒槌」，一个是「小绒球」。",gj:"银花如棒槌，菊花似绒球"},
 {a:"黄芪",b:"甘草",sA:"切片断面\u201c金盏银盘\u201d、皮部有菊花心状裂隙，嚼之有豆腥味",sB:"外皮红棕、断面纤维性，入口味甜而特殊",tip:"黄芪饮片断面有著名的<b>「金盏银盘」</b>：外层黄白、中心鲜黄，皮部有菊花心状裂隙，嚼之有<b>豆腥味</b>；甘草外皮红棕、断面纤维性，最标志性的是<b>味甜而特殊</b>——「国老」的甜是刻进药骨里的。",gj:"黄芪金盏银盘豆腥气，甘草红皮入口甜"},
 {a:"当归",b:"党参",sA:"断面黄白色、散布棕色油点（朱砂点），香气浓郁特异",sB:"根头顶部有密集疣状突起的茎痕（狮子盘头），气微味微甜",tip:"当归表面黄棕色，断面黄白色、散布<b>棕色油点（朱砂点）</b>，香气浓郁特异；党参根头顶有密集疣状突起的茎痕，人称<b>「狮子盘头」</b>，断面有裂隙或放射状纹理，气微、味微甜。",gj:"当归朱砂点，党参狮子头"},
 {a:"山药",b:"天麻",sA:"表面黄白光滑，断面洁白、富粉性",sB:"一端有红棕色干枯芽苞（鹦哥嘴），断面角质半透明",tip:"山药表面黄白、有纵沟，断面<b>洁白、富粉性</b>；天麻一端有红棕色干枯芽苞，人称<b>「鹦哥嘴」</b>，另一端有圆脐形疤痕（像肚脐眼），断面角质、<b>半透明</b>有光泽。",gj:"山药白胖带粉，天麻鹦哥嘴上戴"},
 {a:"陈皮",b:"青皮",sA:"成熟果皮，色橙红、内面白色海绵状，质薄而软",sB:"未成熟果皮，色青黑、质硬皮厚，气味峻烈",tip:"陈皮是<b>成熟</b>橘子的果皮：色橙红或红棕，外露油点、内面白色海绵状，质薄而软；青皮是<b>未成熟</b>的青色果皮或幼果：色青黑、质硬、皮厚，气味更峻烈。同源不同龄，越生越猛。",gj:"陈皮红软性温和，青皮色青力更峻"},
 {a:"枸杞子",b:"五味子",sA:"长卵形，表面红色至暗红、皱缩，味甘微酸",sB:"小球形浆果干缩而成，尝一口五味俱全",tip:"枸杞子呈<b>长卵形</b>：表面红色至暗红、皱缩，顶端有小凸起状花柱痕，味甘、微酸；五味子是<b>小球形</b>浆果干缩而成，皱缩成团，五味俱全——酸、甘、辛、苦、咸一样不落。",gj:"枸杞长卵甜微酸，五味圆球五样味"}
];
const KB=[
 ...LOOKALIKES.map(l=>({keys:[`${l.a}和${l.b}`,`${l.b}和${l.a}`,`${l.a}与${l.b}`,`${l.b}与${l.a}`,`区分${l.a}`,`区分${l.b}`,`分辨${l.a}`,`分辨${l.b}`,`辨别${l.a}`,`辨别${l.b}`,`${l.a}相似`,`${l.b}相似`],cat:`辨别 · ${l.a}/${l.b}`,ans:`<b>火眼金睛 · ${l.a} vs ${l.b}</b><div class="kv"><span class="k">分辨要点</span>${l.tip}</div><div class="kv"><span class="k">药童口诀</span>「${l.gj}」</div><div style="margin-top:8px"><button class="btn ghost" onclick="go('game')">去知识竞赛练练辨药眼力 →</button></div>`})),
 ...ALL_HERBS.map(h=>({keys:[h.n],...(h.cat?{}:{herb:h.n}),ans:`<b>${h.n}</b><div class="kv"><span class="k">性味归经</span>${h.f}</div><div class="kv"><span class="k">外观辨识</span>${h.x}</div><div class="kv"><span class="k">功效主治</span>${h.e}</div><div class="kv"><span class="k">经典出处</span>${h.s}</div><div class="kv"><span class="k">深入阅读</span>${h.b}</div>${h.cat?`<div class="kv" style="color:var(--ink2)">◈ 归入「${h.cat}」类 · 见问答页「本草名录」</div>`:""}`,cat:h.n})),
 ...FORMULAS.map(f=>{const base=f.n.replace(/（[^）]*）/g,"");return {keys:[f.n,base,base.replace("丸","").replace("散","").replace("汤","")],ans:`<b>${f.n}</b><div class="kv"><span class="k">组成</span>${f.comp}</div><div class="kv"><span class="k">方书源流</span>${f.s}</div><div class="kv"><span class="k">方义主治</span>${f.d}</div><div class="kv"><span class="k">深入阅读</span>${f.b}</div>`,cat:f.n};}),
 ...ACUP.map(a=>({keys:[a.n],ans:`<b>穴位 · ${a.n}</b><div class="kv"><span class="k">所属经络</span>${a.m}</div><div class="kv"><span class="k">定位</span>${a.loc}</div><div class="kv"><span class="k">功效主治</span>${a.d}</div><div class="kv"><span class="k">深入阅读</span>${a.b}</div>`,cat:a.n})),
 ...TOPICS.map(t=>({keys:[t.n,...(t.k||[])],topic:1,ans:`<b>${t.n}</b><div class="kv"><span class="k">本草智答</span>${t.d}</div><div class="kv"><span class="k">深入阅读</span>${t.b}</div>`,cat:t.n}))
];
const SYNONYM={"黄耆":"黄芪","杞子":"枸杞子","忍冬":"金银花","六味地黄":"六味地黄丸","三里":"足三里","人参须":"人参","菊花茶":"菊花","枸杞茶":"枸杞子","洋参":"人参","熟地":"六味地黄丸","按摩哪个穴位":"穴位","艾灸":"足三里"};
