 ["气虚质",["气虚体质","气虚质","气虚"]],
 ["阳虚质",["阳虚体质","阳虚质","阳虚"]],
 ["阴虚质",["阴虚体质","阴虚质","阴虚"]],
 ["痰湿质",["痰湿体质","痰湿质","痰湿","湿气体质"]],
 ["湿热质",["湿热体质","湿热质","湿热"]],
 ["血瘀质",["血瘀体质","血瘀质","血瘀"]],
 ["气郁质",["气郁体质","气郁质","气郁","肝郁"]],
 ["特禀质",["特禀体质","特禀质","过敏体质","特禀"]]
