const SEASON_GREET={
 春:{q:"春三月，此谓发陈。天地俱生，万物以荣。",w:"万物生发的时节，正好翻开《黄帝内经》学养生，把阳气一起\u201c发\u201d起来"},
 夏:{q:"夏三月，此谓蕃秀。天地气交，万物华实。",w:"草木蕃秀的时节，心火当令，读一卷《饮膳正要》清清爽爽过夏天"},
 秋:{q:"秋三月，此谓容平。天气以急，地气以明。",w:"天高物燥的时节，宜润肺防燥，宜读一卷《随息居饮食谱》"},
 冬:{q:"冬三月，此谓闭藏。水冰地坼，无扰乎阳。",w:"万物闭藏的时节，早卧晚起，围炉读《伤寒论》最相宜"}
};
function updateSeasonImg(){const si=$("#seasonImg");if(si)si.src="assets/"+SEASON_IMG[seasonOf()];}
function seasonOf(){
  if(window._seasonOv)return window._seasonOv; // 四季预览：人工切换优先于真实节气
  const n=new Date(),m=n.getMonth()+1,d=n.getDate();
  return (m>11||(m===11&&d>=7)||m<2||(m===2&&d<4))?"冬":(m<5||(m===5&&d<6))?"春":(m<8||(m===8&&d<8))?"夏":"秋";
}
/* 当季飘落物：春花瓣 · 夏流萤 · 秋红叶 · 冬初雪（纯 CSS 动画，关闭系统动效时自动隐藏） */
function buildSeasonFx(s){
  let fx=document.getElementById("seasonFx");
  if(!fx){fx=document.createElement("div");fx.id="seasonFx";document.body.appendChild(fx);}
  const C={春:"❀",夏:"✦",秋:"❦",冬:"❄"};
  let h="";
  for(let i=0;i<18;i++){
    h+=`<span style="left:${(Math.random()*100).toFixed(1)}vw;font-size:${(10+Math.random()*12).toFixed(1)}px;animation-duration:${(8+Math.random()*9).toFixed(1)}s;animation-delay:${(-Math.random()*17).toFixed(1)}s;opacity:${(.4+Math.random()*.45).toFixed(2)}">${C[s]}</span>`;
  }
  fx.innerHTML=h;
}
/* 四季预览切换：更衣 + 换飘落物 + 今日荐读跟随当季重算 */
function setSeason(s){
  window._seasonOv=s;
  document.documentElement.dataset.season=s;
  buildSeasonFx(s);
  document.querySelectorAll(".season-bar button").forEach(b=>b.classList.toggle("on",b.dataset.s===s));
  if(typeof renderBooks==="function")renderBooks();
  if(typeof renderChips==="function")renderChips(); // 快捷问题随季更衣
  updateSeasonImg(); // 当季插画同步更换
}
document.documentElement.dataset.season=seasonOf(); // 四季换肤：主色随节气更衣
buildSeasonFx(seasonOf());
document.querySelectorAll(".season-bar button").forEach(b=>b.classList.toggle("on",b.dataset.s===document.documentElement.dataset.season));
/* 经典书目接入问答库：问书名（含别名）即答完整书卡，unshift 保证与同名话题打平时书卡优先 */
