BOOKS.push(
 {t:"金匮要略",au:"· 张仲景 · 东汉",d:"《伤寒杂病论》的杂病部分，与《伤寒论》并称仲景双璧。以内科杂病为纲，辨脏腑经络论治，载方二百余首，是中医临床方书的源头。",hl:"见肝之病，知肝传脾，当先实脾。",hs:"——《金匮要略·脏腑经络先后病脉证》",diff:"硬核",why:"「治未病」不只是口号，这一句讲的是疾病传变的预判与截断，读它最能体会中医的整体观。",tg:["临床","方剂"],fit:["气郁质","痰湿质"]},
 {t:"脾胃论",au:"· 李杲（号东垣） · 金元",d:"补土派代表作。李东垣身处战乱饥馑，见人多因脾胃内伤致病，遂立「内伤脾胃，百病由生」之说，创补中益气汤等名方。",hl:"脾胃之气既伤，而元气亦不能充，而诸病之所由生也。",hs:"——《脾胃论·脾胃虚实传变论》",diff:"进阶",why:"把「吃饭」提到元气本源的高度。久坐、节食、思虑过度的现代人，读来格外扎心。",tg:["理论","养生"],fit:["气虚质","阳虚质"]},
 {t:"温疫论",au:"· 吴又可（名有性） · 明",d:"中国第一部传染病学专著。明末大疫，吴又可跳出「伤寒」框架，提出戾气自口鼻而入、各有专病之邪，为温病学先声。",hl:"温疫之为病，非风非寒非暑非湿，乃天地间别有一种异气所感。",hs:"——《温疫论·原病》",diff:"进阶",why:"在细菌病毒被发现前两百多年，已猜到「有一物专致一病」，是中医史上最漂亮的推理之一。",tg:["临床","理论"],fit:["湿热质"]},
 {t:"医林改错",au:"· 王清任 · 清",d:"王清任亲赴义冢观察人体脏腑，纠正古书脏腑图之误，并创立以气血立论的逐瘀诸方，血府逐瘀汤至今常用。",hl:"治病之要诀，在明白气血。",hs:"——《医林改错·气血合脉说》",diff:"进阶",why:"一位敢说「古书写错了」的清代医家。读它不只为方，更为那份实证精神。",tg:["临床","文化"],fit:["血瘀质"]},
 {t:"针灸大成",au:"· 杨继洲 · 明",d:"集明以前针灸学之大成，汇经络腧穴、刺法灸法与各家歌赋，《四总穴歌》即赖此书广传，是针灸入门与检索的枢纽。",hl:"肚腹三里留，腰背委中求，头项寻列缺，面口合谷收。",hs:"——《针灸大成·四总穴歌》",diff:"入门",why:"四句口诀把全身常见不适对应到四个要穴，背下来就是一张随身穴位地图。",tg:["针灸","启蒙"],fit:["平和质","血瘀质"]},
 {t:"濒湖脉学",au:"· 李时珍 · 明",d:"李时珍以二十七脉为纲，用歌诀体写脉象、主病与相似脉辨别，把「只可意会」的脉学变成可诵可记的入门课本。",hl:"浮脉，举之有余，按之不足。",hs:"——《濒湖脉学·浮脉》",diff:"入门",why:"《本草纲目》作者的另一本小书，篇幅不大却是脉学第一启蒙书，读着读着就想给自己把把脉。",tg:["诊法","启蒙"],fit:["平和质"]},
 {t:"本草经集注",au:"· 陶弘景 · 南朝梁",d:"陶弘景整理《神农本草经》并增补新药，首创按药物自然属性分玉石、草木、虫兽等部类，奠定后世本草分类学的基础。",hl:"诸药所生，皆有境界。",hs:"——《本草经集注·序录》",diff:"进阶",why:"最早认真讨论「道地药材」的书：同一味药，产地不同，药力确有分别。",tg:["本草","理论"],fit:["平和质"]},
 {t:"食疗本草",au:"· 孟诜 · 唐（张鼎补）",d:"现存最早的食疗专著，逐味记载日常食物的性味、功效、食忌与四季宜忌，把「药食同源」落到一饭一蔬上。",hl:"药食同源，日用之品皆可入馔疗疾。",hs:"◈ 药童辑要（据《食疗本草》内容概括）",diff:"入门",why:"没有高深理论，全是厨房里的事：什么该多吃、什么要忌口，最贴日常。",tg:["食疗","养生"],fit:["痰湿质","气虚质"]}
);
Object.assign(BOOK_ALIASES,{"金匮要略":["金匮","要略"],"脾胃论":["东垣","补土派"],"温疫论":["瘟疫论","吴又可"],"医林改错":["逐瘀"],"针灸大成":["四总穴歌"],"濒湖脉学":["脉学"],"本草经集注":["集注"],"食疗本草":["孟诜"]});
/* 新增典籍的原文选读：2 段原文 + 白话 + 药童领读；不确定原文的以「辑要」明确标注，不冒充古籍原句 */
Object.assign(BOOK_READS,{
 "金匮要略":{
  ps:[
   {t:"脏腑经络先后病脉证",s:"见肝之病，知肝传脾，当先实脾。",tr:"见到肝病，就要知道它容易传变到脾，所以应当先调补脾脏，让脾土健旺以阻断病势——这是「治未病」在临床上的具体用法。"},
   {t:"脏腑经络先后病脉证",s:"若五脏元真通畅，人即安和。",tr:"只要五脏的真气运行通畅，人体就安宁和顺。把健康落在气机通畅上，而非单纯「补」。",}],
  g:"先读第一篇《脏腑经络先后病脉证》，把「传变」与「元真通畅」两句想明白，后面各病篇都顺了。"},
 "脾胃论":{
  ps:[
   {t:"脾胃虚实传变论",s:"脾胃之气既伤，而元气亦不能充，而诸病之所由生也。",tr:"脾胃之气一旦受损，元气也就得不到充养，各种疾病便由此发生。饮食失节、劳倦过度、思虑太甚，都算伤脾。"},
   {t:"脾胃胜衰论 · 药童辑要",s:"（辑要）升发脾阳、甘温除热，是东垣补土一派的核心笔法。",tr:"李东垣治气虚发热不用苦寒泻火，而以黄芪、人参、白术等甘温之品升举脾阳，代表方即补中益气汤。此段为内容辑要，非原文。"}],
  g:"抓住「元气靠脾胃养」一条主线，再看补中益气汤的组方，就能读懂金元四大家为何各立一派。"},
 "温疫论":{
  ps:[
   {t:"原病",s:"温疫之为病，非风非寒非暑非湿，乃天地间别有一种异气所感。",tr:"瘟疫这类病，不是风、寒、暑、湿等常规外邪所致，而是天地间另有一种特殊的「异气」感染人体而成。"},
   {t:"原病 · 药童辑要",s:"（辑要）邪自口鼻而入，各随其气而成各病。",tr:"吴又可认为戾气从口鼻侵入，且不同戾气引发不同病证，已隐约触及病原特异性与传染途径。此段为内容辑要，非原文。"}],
  g:"先读《原病》一篇，看古人如何在没有显微镜的年代，靠观察与推理逼近传染病真相。"},
 "医林改错":{
  ps:[
   {t:"气血合脉说",s:"治病之要诀，在明白气血。",tr:"治病最关键的诀窍，在于把气与血的关系、虚实、通滞弄明白。"},
   {t:"医林改错 · 药童辑要",s:"（辑要）亲验脏腑以正古图之误，立逐瘀诸方以治瘀血诸证。",tr:"王清任依据实地观察订正前代脏腑图，并以活血化瘀立法创制血府逐瘀汤、膈下逐瘀汤等方。此段为内容辑要，非原文。"}],
  g:"卷首的脏腑改正图与后半的逐瘀方要连着读：一位医家的实证勇气，最后落到了能救人的方子上。"},
 "针灸大成":{
  ps:[
   {t:"四总穴歌",s:"肚腹三里留，腰背委中求，头项寻列缺，面口合谷收。",tr:"腹部不适取足三里，腰背酸痛取委中，头项之疾取列缺，面部口齿之病取合谷——四个要穴统摄全身常见部位。"},
   {t:"针灸大成 · 药童辑要",s:"（辑要）循经取穴，辨虚实而行补泻，灸药各有所宜。",tr:"本书汇辑明以前经络、腧穴、刺灸法与医案，强调按经脉循行选穴并据虚实施以补泻。此段为内容辑要，非原文。"}],
  g:"把《四总穴歌》抄在笔记本第一页，再回头翻经络图，穴位就不再是散点而成了路线。"},
 "濒湖脉学":{
  ps:[
   {t:"浮脉",s:"浮脉，举之有余，按之不足。",tr:"浮脉的特点：轻按即得且有力，重按反而觉得不足。多主表证，是脉学入门的第一条。"},
   {t:"濒湖脉学 · 药童辑要",s:"（辑要）二十七脉分纲别类，辨相似脉以免混淆。",tr:"全书以七言歌诀描述二十七种脉象及其主病，并专列「相类脉」辨别，便于记诵与临证对照。此段为内容辑要，非原文。"}],
  g:"不必一次背完二十七脉，先辨「浮、沉、迟、数」四纲，再往外扩，脉学就不吓人了。"},
 "本草经集注":{
  ps:[
   {t:"序录",s:"诸药所生，皆有境界。",tr:"各种药材的生长，各有其适宜的产地与环境——这正是后世「道地药材」观念最早的经典表述之一。"},
   {t:"本草经集注 · 药童辑要",s:"（辑要）以朱墨分书《本经》与别录，按自然属性分部类。",tr:"陶弘景用朱、墨两色区分《神农本草经》原文与后世增补，并首创玉石、草木、虫兽、果菜、米食等分类法。此段为内容辑要，非原文。"}],
  g:"读它像读一本「古籍整理说明书」：古人如何分类、如何标注出处，比单记药名更有意思。"},
 "食疗本草":{
  ps:[
   {t:"食疗本草 · 药童辑要",s:"（辑要）日常食物各有性味，用之得宜可养可疗，失宜则反为害。",tr:"全书逐一记录食药的性味、功效、食忌与配伍宜忌，把调养落到三餐之中。此段为内容辑要，非原文。"},
   {t:"食疗本草 · 药童辑要",s:"（辑要）因时、因人、因病而忌口，是食疗的第一要义。",tr:"同一味食物，四时不同、体质不同、病证不同，宜忌亦随之变化，与本站「先识体质再荐读」是同一思路。此段为内容辑要，非原文。"}],
  g:"把它当一本「厨房版本草」翻，配着《随息居饮食谱》一起读，药食同源这条线就完整了。"}
});
KB.unshift(...BOOKS.map(b=>({keys:[b.t,...(BOOK_ALIASES[b.t]||[])],cat:b.t,ans:`<b>经典 · 《${b.t}》</b><div class="kv"><span class="k">作者年代</span>${b.au}</div><div class="kv"><span class="k">名句金句</span>\u201c${b.hl}\u201d${b.hs}</div><div class="kv"><span class="k">内容看点</span>${b.d}</div><div class="kv"><span class="k">药童导读</span>${b.why}</div><div class="kv"><span class="k">难度与适合</span>${b.diff} · 适合${b.fit.join("、")}</div><div style="margin-top:8px"><button class="btn ghost" onclick="openRead('${b.t}')">📖 翻开《${b.t}》读选段 →</button></div><div class="kv" style="color:var(--ink2)">完整金句卡与荐读路线，去「经典荐读」页面翻翻〜</div>`})));
/* ===== 经典作者档案：问「李时珍是谁」「本草纲目的作者是谁」都能聊 ===== */
const AUTHORS={
 "黄帝内经":{n:"佚名医家（托名黄帝与岐伯）",era:"战国至秦汉",names:["黄帝","岐伯","岐黄"],bio:"《内经》并非黄帝亲笔，而是战国至秦汉间众多医家的集体智慧，假托黄帝与岐伯君臣问答以示学问正统。今日中医雅称「岐黄之术」，正是从这两位\u201c署名作者\u201d而来。",fun:"黄帝负责提问，岐伯负责回答——史上最成功的\u201c学术双人相声\u201d，一演就是两千年。"},
 "神农本草经":{n:"佚名（托名神农）",era:"汉代成书",names:["神农"],bio:"\u201c神农尝百草\u201d只是传说，书成于汉代，由无名医家整理先秦用药经验而成。托名农耕始祖神农，表达的是\u201c药食同源\u201d的敬意。",fun:"神农本人若读到此书大概会疑惑：我尝过的草，怎么有好几味连我在书里都没见过？"},
 "伤寒论":{n:"张仲景（名机）",era:"东汉",names:["张仲景","仲景"],bio:"东汉南阳人，被尊为「医圣」。因宗族十年间三分之二死于疫病，愤而\u201c勤求古训，博采众方\u201d，著《伤寒杂病论》，后世整理为《伤寒论》与《金匮要略》两部分。",fun:"民间传说他发明了饺子（\u201c祛寒娇耳汤\u201d）给冻伤的乡亲治病——医圣的副业也很治愈。"},
 "本草纲目":{n:"李时珍（字东璧）",era:"明（1518-1593）",names:["李时珍","时珍"],bio:"湖北蕲州人。因发现旧本草谬误颇多，\u201c渔猎群书，搜罗百氏\u201d，历时27年、三易其稿著成《本草纲目》，此后又奔走十年促成刻印，遗嘱仍是进献此书。",fun:"为写本草他亲口试药、上山采标本，还专门养过一条蛇观察习性——明代的\u201c硬核科普博主\u201d。"},
 "千金方":{n:"孙思邈",era:"唐",names:["孙思邈","思邈"],bio:"京兆华原（今陕西铜川）人，尊称「药王」。以\u201c人命至重，有贵千金\u201d立书名，开篇《大医精诚》是中国医德的千古典范。相传他活过百岁，是史上最长寿的医家之一。",fun:"唐太宗都召他入宫请教养生之道，他却一心扎根民间行医——皇帝的面子大不过百姓的病。"},
 "温病条辨":{n:"吴鞠通（名瑭）",era:"清",names:["吴鞠通","吴瑭","鞠通"],bio:"江苏淮安人。19岁父亲病故，愤而弃科举学医，后著《温病条辨》，确立温病三焦辨证体系，银翘散、桑菊饮等名方皆出其手。",fun:"他因亲人病故而学医——从\u201c焦虑的家属\u201d到温病学派集大成者，这份执念改写了中医史。"},
 "汤头歌诀":{n:"汪昂（字讱庵）",era:"清初",names:["汪昂","讱庵"],bio:"安徽休宁人，本为明末秀才，入清后弃科举、专攻医药普及，另著有《本草备要》。《汤头歌诀》把方剂编成七言歌诀，是学方的启蒙第一书。",fun:"古代医界\u201c押韵狂魔\u201d：把几百首方剂全写进七言歌词里，背下来就等于方剂学入门。"},
 "随息居饮食谱":{n:"王孟英（名士雄）",era:"清",names:["王孟英","王士雄","孟英"],bio:"浙江海宁人，温病四大家之一。幼年丧父、家贫自学，一生行医于乱世。《随息居饮食谱》载食药330种，是\u201c药食同源\u201d理念的通俗读本。",fun:"他的书斋名「随息居」，大意是\u201c随遇而安地过日子\u201d——乱世医家的淡然，都写在书名里了。"},
 "难经":{n:"相传扁鹊（秦越人）",era:"战国",names:["扁鹊","秦越人"],bio:"扁鹊本名秦越人，渤海郡人，脉学的开山宗师。《难经》以八十一个问答\u201c举难释疑\u201d，相传出自他手（学界认为成书当在汉代）。",fun:"「望而知之谓之神」的段位表出自此书——若按此标准，扁鹊见蔡桓公那一眼，堪称神级开局。"},
 "肘后备急方":{n:"葛洪（号抱朴子）",era:"东晋",names:["葛洪","抱朴子"],bio:"江苏句容人，炼丹家、医药学家双修。《肘后备急方》专收\u201c简、便、验、廉\u201d的急救之法，屠呦呦循\u201c青蒿一握\u201d记载获灵感提取青蒿素，摘得诺贝尔奖。",fun:"他在深山炼丹时顺手记下的方子，一千六百年后救了数百万疟疾患者——炼丹的副业救了医学的场子。"},
 "医学三字经":{n:"陈修园（名念祖）",era:"清",names:["陈修园","陈念祖","修园"],bio:"福建长乐人，医学教育家。一生致力于中医普及、著作等身，《医学三字经》把中医源流、诊法方药编成三字韵语，是医史入门第一书。",fun:"清代中医界的\u201c教材编写组组长\u201d：他写的启蒙读物，至今仍是中医爱好者的开学第一课。"},
 "饮膳正要":{n:"忽思慧",era:"元",names:["忽思慧"],bio:"元代宫廷饮膳太医，兼通蒙汉医药与营养之学，主持编成中国第一部营养学专著《饮膳正要》，讲妊娠食忌、饮酒避忌、四时所宜。",fun:"身份相当于元代皇家「首席营养师」，给皇帝一家写膳食说明书，一写写成了传世经典。"}
};
Object.assign(AUTHORS,{
 "金匮要略":{n:"张仲景（名机）",era:"东汉",names:["金匮","仲景杂病"],bio:"与《伤寒论》同出《伤寒杂病论》，后世将杂病部分整理为《金匮要略》。全书以脏腑经络为纲辨治内伤杂病，载方精审，被奉为中医临床方书之祖。",fun:"同一部书被后人拆成《伤寒论》与《金匮要略》两本流传——医圣大概没想到自己「一书两版」。"},
 "脾胃论":{n:"李杲（号东垣老人）",era:"金元",names:["李东垣","李杲","东垣"],bio:"金元四大家之一、补土派宗师。师从张元素，值战乱饥馑见百姓多因劳倦伤脾致病，遂著《脾胃论》，创补中益气汤，人称「医之有李东垣，如儒家之有孟子」。",fun:"别人打仗抢地盘，他打仗抢「脾胃」——一句「内伤脾胃，百病由生」影响了此后八百年的养生观。"},
 "温疫论":{n:"吴有性（字又可）",era:"明末",names:["吴又可","吴有性"],bio:"江苏吴县人。崇祯年间大疫流行，他发现套用伤寒法治之无效，遂深入疫区观察，著《温疫论》提出「戾气」致病，比病原微生物学说早了两个多世纪。",fun:"在没有显微镜的年代，他靠「这病会人传人、且一种气致一种病」的观察，把传染病学往前推了一大步。"},
 "医林改错":{n:"王清任（字勋臣）",era:"清（1768-1831）",names:["王清任","勋臣"],bio:"河北玉田人。为订正古医书脏腑图，多次赴义冢、刑场实地观察人体，绘《亲见改正脏腑图》，并据气血理论创制逐瘀诸方，是清代最具实证精神的医家。",fun:"书名直译就是「我要给医林改错」——古人少有的、敢把质疑写进标题的狠人。"},
 "针灸大成":{n:"杨继洲（名济时）",era:"明",names:["杨继洲","继洲"],bio:"浙江衢州人，世代业医、尤精针灸，曾任太医院医官。以家传《卫生针灸玄机秘要》为底，广辑明以前二十余家针灸文献，编成《针灸大成》十卷。",fun:"今天的「四总穴歌」能背得这么顺，全靠他把散落各家的歌诀收进了一本书。"},
 "濒湖脉学":{n:"李时珍（号濒湖）",era:"明",names:["濒湖","李时珍"],bio:"《本草纲目》作者，亦精脉诊。因感前人脉学「文字深奥，学者难明」，遂以歌诀体重编二十七脉，成《濒湖脉学》，与《奇经八脉考》并行于世。",fun:"写得了 190 万字巨著，也肯为一本入门小册子押韵——大医家的科普自觉。"},
 "本草经集注":{n:"陶弘景（号华阳隐居）",era:"南朝梁（456-536）",names:["陶弘景","弘景","华阳隐居"],bio:"丹阳秣陵人，道士、医药学家、博物学家。整理《神农本草经》并增补 365 味成《本草经集注》，首创药物自然属性分类法，兼注产地、采制与真伪。",fun:"梁武帝每有国家大事都写信问他，人称「山中宰相」——隐居茅山，却管着半个朝堂。"},
 "食疗本草":{n:"孟诜（shēn）",era:"唐（621-713）",names:["孟诜"],bio:"汝州梁县人，孙思邈弟子，曾任同州刺史。所撰《补养方》后由张鼎增补为《食疗本草》，是我国现存最早的食疗专书，专记日常食物的性味与食忌。",fun:"当过刺史、写过食疗书：把「今天吃什么」这件小事，写成了传世经典。"}
});
const AUTHOR2BOOK={};Object.keys(AUTHORS).forEach(bt=>AUTHORS[bt].names.forEach(n=>AUTHOR2BOOK[n]=bt));
function authorCard(bt){
  const a=AUTHORS[bt];
  return `<b>作者 · ${a.n}</b><div class="kv"><span class="k">年代</span>${a.era}</div><div class="kv"><span class="k">其人其事</span>${a.bio}</div><div class="kv"><span class="k">药童八卦</span>${a.fun}</div><div style="margin-top:8px"><button class="btn ghost" onclick="openRead('${bt}')">📖 看看《${bt}》里的金句 →</button></div><div class="kv" style="color:var(--ink2)">竞赛「经典考点」也会考作者哦，去「百草试炼」页过过招〜</div>`;
}
const STATES={"1":"没有","2":"偶尔","3":"有时","4":"经常","5":"总是"};
let quizAns={},lastQuiz=null;
const $=s=>document.querySelector(s);

document.querySelectorAll("#nav button").forEach(b=>b.onclick=()=>go(b.dataset.p));
/* ===== 首页路线图 ↔ 功能卡双向联动：悬停任一方，另一方点亮呼应 ===== */
document.querySelectorAll(".home-steps .step[data-p]").forEach(st=>{
  const card=document.querySelector(`.home-feats .feat[data-p="${st.dataset.p}"]`);
  if(!card)return;
  const on=()=>{st.classList.add("hl");card.classList.add("hl");};
  const off=()=>{st.classList.remove("hl");card.classList.remove("hl");};
  st.addEventListener("mouseenter",on);st.addEventListener("mouseleave",off);
  card.addEventListener("mouseenter",on);card.addEventListener("mouseleave",off);
});

/* ===== 惰性挂载：7 个页面初始只留空壳，首次进入才注入模板并生成数据视图 ===== */
const PAGE_MOUNTED={home:true};
const PAGE_INIT={
  quiz:()=>{renderQuiz();restorePhys();},
  chat:()=>{renderKbIndex();renderChips();},    // MPA：推荐问题须本页渲染（SPA 时代靠 go() 刷新）
  read:()=>{renderFilter();renderBooks();},     // 筛选条 + 二十张书卡
  album:()=>{renderAlbum();},                   // MPA：集章墙须本页渲染（SPA 时代靠 go() 刷新）
  game:()=>{
    const g=window._game;
    const bot=$("#gameBot");if(bot)bot.style.display=g&&g.mode==="contest"?"flex":"none";
    if(g&&g.finished)return;                                        // 已结算：保留成绩页 DOM，不重开题面
    if(g&&g.started)return renderGameQ();                           // 进行中：回到本页恢复题面
    if(g&&g.mode==="contest"&&!g.started)return renderContestReady(); // 已选竞赛但未确认开卷
    renderGameIdle();                                               // 待机：不出题、不计时
  },
  checkin:()=>{renderCheckin();},               // MPA：打卡日历须本页渲染（SPA 时代靠 go() 刷新）
  materia:()=>{renderMateria();},               // 本草名方：本草名录 + 名方要诀 两 tab
  acupoint:()=>{renderAcupoint();},             // 经络要穴：独立页，12 处要穴卡片
  seasons:()=>{const q=new URLSearchParams(location.search).get("s");renderFourSeasons(q&&FOUR_KEYS.indexOf(q)>=0?q:seasonOf());} // 四时调神：支持 ?s=秋 直达某季
};
/* ===== 本草名方：本草 + 名方两栏卡片，数据驱动，可一键问小药童 ===== */
function renderMateria(){
  const setCnt=(id,v)=>{const el=document.getElementById(id);if(el)el.textContent=v;};
  setCnt("cntHerb",ALL_HERBS.length);setCnt("cntFormula",FORMULAS.length);
  const hb=$("#matHerb");
  if(hb && !hb.dataset.done){
    let html=`<div class="mat-note">◈ 本草：草木金石虫兽，皆入药笼。下列 <b>${ALL_HERBS.length}</b> 味按功效分门；带「🖌 工笔」者另有手绘画像，见「本草图鉴」。</div>`;
    html+=`<div class="mat-grp"><h3 class="mat-h3">药食同源 · 工笔本草（${HERBS.length} 味）</h3><div class="mat-grid">`+HERBS.map(h=>herbCard(h,true)).join("")+`</div></div>`;
    HERB_CATS.forEach(c=>{
      const list=MATERIA_EXTRA.filter(h=>h.cat===c);
      if(!list.length)return;
      html+=`<div class="mat-grp"><h3 class="mat-h3">${c}（${list.length} 味）</h3><div class="mat-grid">`+list.map(h=>herbCard(h,false)).join("")+`</div></div>`;
    });
    hb.innerHTML=html; hb.dataset.done="1";
  }
  const fm=$("#matFormula");
  if(fm && !fm.dataset.done){
    fm.innerHTML=`<div class="mat-note">◈ 名方：组成、方义、源流，一卡尽览。点「问小药童」可追问配伍与禁忌。</div><div class="mat-grid">`+FORMULAS.map(formulaCard).join("")+`</div>`;
    fm.dataset.done="1";
  }
}

/* ===== 经络要穴：独立页，ACUP 数据驱动的穴位卡片 ===== */
function renderAcupoint(){
  const cnt=document.getElementById("cntAcup");if(cnt)cnt.textContent=ACUP.length;
  const ac=$("#acupArea");
  if(ac && !ac.dataset.done){
    ac.innerHTML=`<div class="mat-note">◈ 穴位：定位、所属经络、功效主治，按经典出处整理。点「问小药童」可追问取穴与手法。</div><div class="mat-grid">`+ACUP.map(acupCard).join("")+`</div>`;
    ac.dataset.done="1";
  }
}

/* ===== 四时调神：复用 SEASON_* / TERMS / ALL_HERBS / BOOKS，只渲染当前季 ===== */
const FOUR_KEYS=["春","夏","秋","冬"];
/* 《素问·四气调神大论》四时原文的白话意译；原文统一取自 SEASON_GREET，不另存第二份 */
const FOUR_TRANSLATION={
 春:"春季的三个月是推陈出新的时节，天地阳气一同升发，草木万物随之繁茂。宜晚睡早起，在庭院中缓步散行，披散头发、松开衣带，让情志随生机自然舒展。",
 夏:"夏季的三个月是草木蕃茂、开花孕果的时节，天地阴阳之气相交，万物由生长走向结实。宜晚睡早起，不嫌日光、不轻易郁怒，使体内气机得以宣通。",
 秋:"秋季的三个月是万物形态安定、成熟平定的时节，天风劲急、地气清肃明朗。宜早睡早起，作息与鸡相近，收敛神气，不使情志过度外驰。",
 冬:"冬季的三个月是阳气封藏的时节，水面结冰、大地冻裂，此时不可扰动体内阳气。宜早睡晚起，等日出再活动，注意保暖，勿使汗出过多而令阳气外泄。"
};
/* 当令本草：只从全站 ALL_HERBS 按名取用，避免药材数据两处维护 */
const FOUR_HERBS={
 春:["薄荷","菊花","枸杞子","黄芪","山药"],
 夏:["金银花","莲子","茯苓","薏苡仁","生姜"],
 秋:["麦冬","桔梗","五味子","陈皮","甘草"],
 冬:["当归","肉桂","干姜","人参","熟地黄"]
};
/* 与 seasonOf() 同一套节气边界：立春 2/4、立夏 5/6、立秋 8/8、立冬 11/7 */
function termSeason(m,d){
  return (m>11||(m===11&&d>=7)||m<2||(m===2&&d<4))?"冬":(m<5||(m===5&&d<6))?"春":(m<8||(m===8&&d<8))?"夏":"秋";
}
function currentTermName(){
  const n=new Date(),m=n.getMonth()+1,d=n.getDate();
  let cur=TERMS[TERMS.length-1];
  for(const x of TERMS){if(m<x[1]||(m===x[1]&&d<x[2]))break;cur=x;}
  return cur[0];
}
function renderFourSeasons(s){
  s=FOUR_KEYS.indexOf(s)>=0?s:seasonOf();
  const box=$("#fourBody");if(!box)return;
  document.querySelectorAll(".four-tab").forEach(b=>b.classList.toggle("on",b.dataset.s===s));
  const greet=SEASON_GREET[s],care=SEASON_CARE[s],rec=SEASON_READS[s];
  const terms=TERMS.filter(t=>termSeason(t[1],t[2])===s);
  const nowTerm=currentTermName();
  const termHtml=terms.map(t=>`<div class="four-term${t[0]===nowTerm?" on":""}">${t[0]===nowTerm?'<span class="ft-now">当 前</span>':""}<b>${t[0]}</b><span class="ft-date">约 ${t[1]} 月 ${t[2]} 日</span><p>${t[3]}</p></div>`).join("");
  const herbHtml=FOUR_HERBS[s].map(n=>ALL_HERBS.find(h=>h.n===n)).filter(Boolean).map(h=>herbCard(h,!h.cat)).join("");
  const bookHtml=rec.list.map(n=>{
    const b=BOOKS.find(x=>x.t===n)||{};
    return `<div class="four-book"><b>${n}</b><p>${b.d||"当季应时荐读，可到经典荐读页翻开原文选段与白话译文。"}</p><button class="btn ghost" onclick="go('read')">去经典荐读 →</button></div>`;
  }).join("");
  box.innerHTML=`
    <img class="season-img" src="assets/${SEASON_IMG[s]}" alt="${s}季水墨插画" loading="lazy" decoding="async">
    <div class="four-sec">
      <h3>壹 · 四时原文</h3>
      <div class="four-hint">原文出自《素问·四气调神大论》，白话为意译</div>
      <div class="four-classic">
        <div class="fc-q">「${greet.q}」</div>
        <div class="fc-src">—— 《素问 · 四气调神大论》</div>
        <div class="fc-tr"><b>白话意译</b>：${FOUR_TRANSLATION[s]}</div>
        <div class="fc-pr">◈ 顺时提要：${care.pr}</div>
      </div>
    </div>
    <div class="four-sec">
      <h3>贰 · ${s}季六节气</h3>
      <div class="four-hint">按本站二十四节气表分组 · 公历日期每年略有浮动 · 当季节气以金色标出</div>
      <div class="four-terms">${termHtml}</div>
    </div>
    <div class="four-sec">
      <h3>叁 · 当令本草</h3>
      <div class="four-hint">从全站本草名录中按季择取，性味功效与「本草名方」页同源</div>
      <div class="mat-grid">${herbHtml}</div>
    </div>
    <div class="four-sec">
      <h3>肆 · 应时荐读</h3>
      <div class="four-hint">${rec.why}</div>
      <div class="four-books">${bookHtml}</div>
    </div>
    <div class="four-foot">
      <button class="btn red" onclick="askKB('${s}季养生')">问问小药童 · ${s}季怎么养 →</button>
      <span style="margin-left:10px">顺时调养还可查阅<a href="materia.html">本草名方</a> · <a href="acupoint.html">经络要穴</a> · <a href="read.html">经典荐读</a></span><br>
      节气与养生条目整理自中医药经典文献及传统岁时知识，仅供科普学习；食疗、进补与穴位按揉因人而异，不构成医疗诊断或治疗建议。
    </div>`;
}
function fourSetSeason(s){
  if(FOUR_KEYS.indexOf(s)<0)return;
  window._seasonOv=s;
  document.documentElement.dataset.season=s;
  buildSeasonFx(s);
  updateSeasonImg();
  renderFourSeasons(s);
  try{history.replaceState(null,"","seasons.html?s="+encodeURIComponent(s));}catch(e){}
}
function fourToday(){
  window._seasonOv=null;
  const s=seasonOf();
  document.documentElement.dataset.season=s;
  buildSeasonFx(s);
  updateSeasonImg();
  renderFourSeasons(s);
  try{history.replaceState(null,"","seasons.html");}catch(e){}
}
function herbCard(h,illust){
  return `<div class="mat-card">
    <div class="mat-card-h"><b>${h.n}</b>${illust?'<span class="mat-badge">🖌 工笔</span>':''}<span class="mat-cat">${illust?'药食同源':h.cat}</span></div>
    <div class="kv"><span class="k">性味归经</span>${h.f}</div>
    <div class="kv"><span class="k">功效主治</span>${h.e}</div>
    <div class="kv"><span class="k">经典出处</span>${h.s}</div>
    <button class="btn ghost mat-ask" onclick="askKB('${h.n}')">问小药童 · ${h.n}</button>
  </div>`;
}
function formulaCard(f){
  return `<div class="mat-card">
    <div class="mat-card-h"><b>${f.n}</b><span class="mat-cat">名方</span></div>
    <div class="kv"><span class="k">组成</span>${f.comp}</div>
    <div class="kv"><span class="k">方书源流</span>${f.s}</div>
    <div class="kv"><span class="k">方义主治</span>${f.d}</div>
    <div class="kv"><span class="k">深入阅读</span>${f.b}</div>
    <button class="btn ghost mat-ask" onclick="askKB('${f.n.replace(/（[^）]*）/g,"")}')">问小药童 · ${f.n.replace(/（[^）]*）/g,"")}</button>
  </div>`;
}
function acupCard(a){
  return `<div class="mat-card">
    <div class="mat-card-h"><b>${a.n}</b><span class="mat-cat">${a.m}</span></div>
    <div class="kv"><span class="k">定位</span>${a.loc}</div>
    <div class="kv"><span class="k">功效主治</span>${a.d}</div>
    <div class="kv"><span class="k">经典出处</span>${a.b}</div>
    <button class="btn ghost mat-ask" onclick="askKB('${a.n}')">问小药童 · ${a.n}</button>
  </div>`;
}
function switchMat(tab){
  document.querySelectorAll(".mat-tab").forEach(b=>b.classList.toggle("on",b.dataset.tab===tab));
  document.querySelectorAll(".mat-pane").forEach(p=>p.classList.toggle("on",p.id==="mat"+tab.charAt(0).toUpperCase()+tab.slice(1)));
}
/* 知识库速查：把全部本草（按功效分门）与典籍列出来，点名字即问药童 */
function renderKbIndex(){
  const box=$("#kbIndex");if(!box)return;
  const btn=(n,label)=>`<button onclick="askKB('${n}')">${label||n}</button>`;
  const cats=HERB_CATS.map(c=>`<div class="kbi-cat"><b>${c}</b>${ALL_HERBS.filter(h=>h.cat===c).map(h=>btn(h.n)).join("")}</div>`).join("");
  const orig=`<div class="kbi-cat"><b>药食同源</b>${HERBS.map(h=>btn(h.n)).join("")}</div>`;
  const books=`<div class="kbi-btns">${BOOKS.map(b=>btn(b.t,`《${b.t}》`)).join("")}</div>`;
  box.innerHTML=`<details class="kbi"><summary>📚 知识库速查 · <b>${ALL_HERBS.length} 味本草</b> / <b>${BOOKS.length} 部典籍</b> —— 点名字直接问药童</summary>
    <div class="kbi-body">
      <div class="kbi-sec"><h4>◈ 典籍索引 · 书名 / 作者 / 金句 / 原文选段（${BOOKS.length} 部）</h4>${books}</div>
      <div class="kbi-sec"><h4>◈ 本草名录 · 按功效分门（${ALL_HERBS.length} 味）</h4>${orig}${cats}</div>
      <p class="kbi-note">以上条目全部进入本草问答与竞赛题库；带工笔插画的 14 味另见「本草图鉴」，典籍可在「经典荐读」点开原文选段。知识内容整理自中医药经典文献，仅供科普学习，不构成医疗建议。</p>
    </div></details>`;
}
function mountPage(p){
  if(PAGE_MOUNTED[p])return;
  PAGE_MOUNTED[p]=true;
  const sec=$("#p-"+p);
  if(sec&&PAGE_HTML[p])sec.innerHTML=PAGE_HTML[p];
  const init=PAGE_INIT[p];if(init)init();
}
function go(p){location.href=(p==="home"?"index":p)+".html";}

/* ===== 小药童：待机 + 点击互动 ===== */
(function(){
  const IDLE="assets/mascot-idle.webp", ACT="assets/mascot-anim.webp";
  const ACT_MS=5100; // 60帧×83ms≈5s，留一点余量
  const TIPS=[
    "上工治未病，不治已病。——《黄帝内经》",
    "春养肝，夏养心，秋润肺，冬补肾。",
    "黄芪泡水好，气虚之人宜，感冒发烧停一停~",
    "睡前泡脚胜吃补药，水温40度刚刚好。",
    "怒伤肝，喜伤心，思伤脾——情绪也是药引子。",
    "饭后百步走，活到九十九。",
    "本草智答在线，有问必答，点上面按钮来聊聊？",
    "人参虽好，可不要贪服哦，辨证进补才有效。"
  ];
  const img=$("#mascot"),bubble=$("#mascotBubble"),hint=$("#mascotHint");
  if(!img)return;
  let acting=false,tipTimer,hintShown=false,tipSeason=null;
  // 动作 WebP（60 帧 / 83ms 每帧 / 约 0.5MB）按需加载，首屏不下载；仅在用户即将互动或自动打招呼时才取
  let actLoaded=false;
  function preloadAct(){if(actLoaded)return;actLoaded=true;const pre=new Image();pre.src=ACT;}
  if(img){img.addEventListener("pointerenter",preloadAct,{once:true});img.addEventListener("touchstart",preloadAct,{once:true});}
  function showTip(){
    const s=seasonOf();
    let t;
    if(tipSeason!==s){
      // 每季第一触：只出当前季节皮肤的限定金句，别季金句不露面
      const g=SEASON_GREET[s];
      t=`【${s}季限定】「${g.q}」${g.w}`;
      tipSeason=s;
    }else{
      t=pick(TIPS);
    }
    bubble.textContent=t;
    bubble.classList.add("show");
    clearTimeout(tipTimer);
    tipTimer=setTimeout(()=>bubble.classList.remove("show"),ACT_MS+1500);
  }
  function act(auto){
    if(acting)return;
    preloadAct();
    acting=true;
    img.classList.add("acting");
    img.src=ACT;
    showTip();
    if(!hintShown){hint.classList.add("hide");hintShown=true;}
    setTimeout(()=>{
      img.src=IDLE;
      img.classList.remove("acting");
      acting=false;
    },ACT_MS);
  }
  img.addEventListener("click",()=>act(false));
  // 进页面 3 秒后自动打个招呼
  setTimeout(()=>act(true),3000);
})();

/* 本草插画映射（每日本草卡 + 看图辨药共用） */
const HERB_IMG={黄芪:"huangqi",当归:"danggui",枸杞子:"gouqi",金银花:"jinyinhua",陈皮:"chenpi",茯苓:"fuling",甘草:"gancao",菊花:"juhua",山楂:"shanzha",生姜:"shengjiang",人参:"renshen",莲子:"lianzi",山药:"shanyao",薄荷:"bohe"};
(function(){
  const doy=Math.floor((Date.now()-new Date(new Date().getFullYear(),0,0))/864e5);
  const h=HERBS[doy%HERBS.length];
  if(!$("#daily"))return;
  unlockHerb(h.n,true); // 每日本草自动集章（静默）
  $("#daily").innerHTML=`<div class="daily-left"><div class="big">${h.n.slice(0,2)}</div><div class="pinyin">每 日 一 味</div></div>
  <div class="daily-main"><span class="daily-tag">◈ 每日本草 · ${new Date().getMonth()+1}月${new Date().getDate()}日</span>
  <h3>${h.n}</h3><div class="flavor">${h.f}</div><p style="font-size:14px">${h.e}</p>
  <div class="src">${h.s}</div>
  <div class="ask"><a href="#" onclick="askKB('${h.n}');return false">问一问「本草智答」：${h.n}怎么吃？ →</a></div></div>
  <div class="daily-pic"><div class="ph"><img src="assets/herbs/${HERB_IMG[h.n]}.webp" alt="${h.n}工笔插画" onerror="this.parentNode.parentNode.style.display='none'" loading="lazy" decoding="async"></div><span class="cap">本 草 对 照</span></div>`;
})();

