const GAME_OK=["答对了！这味药跟你有缘〜","好眼力！药童考不倒你。","正是此药！看来你没白来药圃。","稳！这题闭着眼都该会〜"];
const GAME_BAD=["哎呀不对，这味其实是","差一点点！正确答案是","药童急得直跺脚：人家叫","此药表示很委屈，明明叫"];
