/* 药童裁判：对错表情 + 台词 */
const GBOT_READY=["第 {n} 题来喽，瞪大眼睛〜","下一味药，接住！","这题我盯着你呢，别偷懒〜","稳住，正常发挥就好〜","药圃里新到一味药，请辨认！"];
const GBOT_CHEER=["中！好眼力，这题难不倒你〜","妙哉！连本药童都要给你竖大拇指！","稳稳命中！记你一功〜","答得又快又准，有当郎中的潜质！","哈哈，正是此药，一点不差！"];
const GBOT_OOPS=["哎呀差一点〜记住它，下回准中！","别灰心，认药都是练出来的〜","嗐，这题有点刁，怪我出得太急〜","不亏不亏，又多认一味药！","没关系，药童陪你慢慢练〜"];
const GBOT_TIMEOUT=["⏱ 超时啦！想好再出手嘛〜","⏱ 手慢了半拍，药都跑喽〜","⏱ 时间到！下一题手脚快些〜"];
function gameReact(state,n){ // state: "ready"|"ok"|"bad"|"timeout"|"end-ok"|"end-mid"|"end-bad"
  const img=$("#gameBotImg"),say=$("#gameBotSay");
  if(!img||!say)return;
  const cls={ok:"happy",bad:"sad",timeout:"sad"};
  img.className="";if(cls[state]){void img.offsetWidth;img.classList.add(cls[state]);}
  say.classList.remove("pop");void say.offsetWidth;say.classList.add("pop");
  const txt=state==="ready"?pick(GBOT_READY).replace("{n}",n)
    :state==="ok"?pick(GBOT_CHEER)
    :state==="timeout"?pick(GBOT_TIMEOUT)
    :state==="bad"?pick(GBOT_OOPS)
    :state==="end-ok"?"满分通关！本药童心服口服，甘拜下风〜"
    :state==="end-mid"?"这份成绩单已经很不错了，随时再来切磋〜"
    :"咳咳……回去多翻翻「经典荐读」，本药童等你雪耻！";
  say.textContent=txt;
}
function shuffleArr(a){a=a.slice();for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;}
