/* 全站通考点题库：中医药文化知识点（体质辨识、药性理论、养生文化）——每题带 root 根源探究 */
const SITE_QS=[
 {q:"下列哪一项不是中医九种体质之一？",opts:["平和质","痰湿质","风寒质","血瘀质"],a:"风寒质",d:1,fb:"九种体质：平和、气虚、阳虚、阴虚、痰湿、湿热、血瘀、气郁、特禀——「风寒质」是冒牌货。",root:"国标九种体质源自王琦「体质九分法」学说，2009 年由中华中医药学会发布为《中医体质分类与判定》标准——表里寒热虚实是证候不是体质，「风寒」治的是证，所以没有它。"},
 {q:"国标《中医体质分类与判定》把判定结果分为哪两档？",opts:["是 / 倾向是","强 / 弱","阳性 / 阴性","主证 / 兼证"],a:"是 / 倾向是",d:1,fb:"本站体质测试的结果页正是按国标给出\u201c是\u201d与\u201c倾向是\u201d两档，并提示兼夹体质。",root:"国标用量表计分再按阈值判定：达到阈值判「是」，接近阈值判「倾向是」——因为体质常是混合的，所以还要提示兼夹体质，本站结果页照此实现。"},
 {q:"中药的「四气」指的是哪四种药性？",opts:["寒热温凉","酸苦甘辛","升降浮沉","君臣佐使"],a:"寒热温凉",fb:"寒、热、温、凉四种药性，平性不占一位——「疗寒以热药，疗热以寒药」正是据此对治。",root:"《神农本草经》已标四气：它是药物作用于人体的反应归纳——能减轻热象者为寒凉、能减轻寒象者为温凉；酸苦甘辛是「五味」，别混啦。"},
 {q:"中医情志学说里，「怒」最容易伤哪一脏？",opts:["肝","心","脾","肺"],a:"肝",fb:"怒伤肝、喜伤心、思伤脾、悲伤肺、恐伤肾——情志过度会伤及对应之脏，养生先养心性。",root:"五志配五脏是《黄帝内经》的藏象纲领：肝主疏泄、在志为怒，大怒则气上而肝失疏泄——历史上「周瑜被三气」的桥段正是这一理论的文学演绎。"},
 {q:"下列哪味既是家常食材，又是经典药材？",opts:["山药","人参","附子","大黄"],a:"山药",fb:"山药、生姜、枸杞、莲子皆入「药食同源」目录——厨房即药房。",root:"「空腹食之为食物，患者食之为药物」（唐·《黄帝内经太素》）正是药食同源的源头表述；国家卫健委专门发布药食同源目录，山药名列其中，而人参、附子、大黄药性峻烈不宜日常食用。"},
 {q:"八段锦这类功法，在中医治法中属于哪一类？",opts:["导引按跷","针刺","汤药","砭石"],a:"导引按跷",d:1,fb:"导引按跷与针、灸、砭、药并列为中医五大治法——八段锦即导引术的现代传承。",root:"《黄帝内经·异法方宜论》提出中央之民「治宜导引按跷」——靠肢体运动配合呼吸导气引体；八段锦宋代已有歌诀记载，正是这套治法的活化石。"},
 {q:"中医九种体质中，被认为最理想、应努力保持的基准体质是？",opts:["平和质","气虚质","湿热质","特禀质"],a:"平和质",fb:"阴阳气血调和、面色红润精力足——平和质是「稳态天花板」，养生的目标就是朝它靠拢。",root:"王琦体质九分法以平和质为基准：其余八种皆为「偏颇体质」，调体养生即是「以平为期」——《内经》「谨察阴阳所在而调之，以平为期」正是理论源头。"},
 {q:"气虚质的人常疲乏气短，下列哪种调养方式最合适？",opts:["黄芪山药炖汤","通宵熬夜","冷饮解暑","剧烈运动"],a:"黄芪山药炖汤",fb:"气虚质宜补气：山药、莲子、黄芪入膳，忌过度劳累，练八段锦正合适。",root:"「劳则气耗」出自《素问·举痛论》——气虚者再熬夜、剧烈运动只会雪上加霜；黄芪补脾肺之气、山药平补三焦，正是本站给气虚质开出的调养锦囊。"},
 {q:"本站「体质辨识」的立意源自《黄帝内经》哪句话？",opts:["上工治未病，不治已病","冬病夏治","以毒攻毒","药食同源"],a:"上工治未病，不治已病",fb:"最高明的医术是让人不生病——体质辨识就是把\u201c治未病\u201d搬到你手边。",root:"《素问·四气调神大论》原句「圣人不治已病治未病，不治已乱治未乱」，并打比方：病已成而后药之，譬犹渴而穿井、斗而铸锥——体质辨识就是这条思想的现代化落地。"}
];
