const ROOTS={
 "上工治未病，不治已病":"《素问·四气调神大论》原句是「圣人不治已病治未病」——用治国打比方：病已成而后药之，譬犹渴而穿井、斗而铸锥，不亦晚乎！",
 "现存最早的药物学专著":"汉代托名神农，实为历代用药经验的累积；「本草」之名由它确立，后世历代本草皆奉它为祖本。",
 "《伤寒论》的作者是":"东汉末年疫病横行，张仲景宗族两百余人不到十年死去三分之二，遂「勤求古训、博采众方」著书——这是一部被苦难逼出来的医书。",
 "方书之祖":"它最早确立「理法方药」一线贯穿的组方规范与君臣佐使配伍原则，后世方书皆从这套范式生长出来，故尊为「祖」。",
 "全书收载药物约多少种":"李时珍发现旧本草错漏百出（常把同一药拆成两味），历时 27 年亲历山野、遍访药农逐一考证修订，终成 1892 种之巨。",
 "人命至重，有贵千金":"孙思邈认为人命比千金还贵重，「一方济之，德逾于此」——书名取「千金」，是把生命价值写进了书名。",
 "《大医精诚》":"「精」指医术精湛、「诚」指心怀至诚——孙思邈把医德写成医家必修课，比西方《日内瓦宣言》早了一千二百多年。",
 "青蒿一握":"葛洪是东晋炼丹家兼医者，书名「肘后」即挂在手肘后随取随用的急救手册；「绞取汁」不用煎煮，恰好保全了青蒿素怕高温的特性——千年前的记载救了现代化学提取。",
 "《温病条辨》的作者是":"乾隆年间多地瘟疫流行，吴鞠通痛感伤寒方对温病无效，在叶天士学说基础上系统化，立三焦辨证纲领成书。",
 "四君子汤中和义":"古无印刷便携之法，医方靠歌诀背诵传承——汪昂把君臣佐使编进七言韵脚，「汤头」即方剂别称，至今仍是中医院校入门读物。",
 "第一部营养学专著":"忽思慧任元代饮膳太医、执掌宫廷饮食养生，把蒙古宫廷食疗经验与中医理论合编成书，孕产、饮酒、四时宜忌俱全。",
 "《难经》相传的作者":"全书以八十一个问答阐释《内经》奥义，「难（nàn）」即问难、质询——独取寸口的诊脉法由此发扬，沿用至今。",
 "载食药330种":"王孟英历经战乱饥荒，晚年寓所名「随息居」，深知乱世食养之要，将 330 种食药按性味分类成谱，是「吃货友好」的食疗经典。",
 "望而知之谓之神":"四诊由表及里：望气色神态、闻声息气味、问病情、切脉象——《难经》以神、圣、工、巧分档，把「望诊」推为最高境界。",
 "的作者是清代医家":"模仿童蒙《三字经》体例、三字一句押韵，从「医之始，本岐黄」一路讲到清代——整部中医史一册通览。",
 "银翘散、桑菊饮":"吴鞠通创辛凉平剂银翘散，取「轻可去实」之意治温病初起——今天药店的银翘解毒片正是由此化裁。",
 "365味药分为":"上品养命应天可久服，中品养性应人需斟酌，下品治病应地多毒不可久服——古人以毒性定品级，而非以药效贵贱。",
 "脑为元神之府":"传统认为「心主神明」，李时珍首次把「元神」安到脑上，为清代王清任「脑髓说」开了先声——超前了那个时代两百多年。",
 "三字韵语":"医史、理法方药、临床各科一册通览，便于蒙童记诵——启蒙读物的生命力就在「朗朗上口」四个字。",
 "始于上焦，在手太阴":"吴鞠通的三焦辨证：温邪上受先犯肺卫（上焦），顺传中焦脾胃、下焦肝肾——给温病画了一张传变地图，与卫气营血辨证互补。",
 "初刊于明代哪一年":"手稿完成后无力刊行，由其子李建元进献朝廷；书成十余年后才在金陵（南京）刊刻问世，李时珍已辞世三年。",
 "由哪两部分组成":"《素问》以黄帝与岐伯问答论医理，「素问」即平素问答之书；《灵枢》详于经络针刺，又称《针经》——二者合璧方为完整《内经》。",
 "东方药物巨典":"以「纲目体」编纂：每药标正名、释名、集解、气味、主治、发明，纲举目张——它不只是药典，更是一部博物学百科全书。"
};
/* ===== 知识库 → 题库自动覆盖：新增本草 / 典籍都能被竞赛与练习考到 =====
   用 push 动态生成（而非静态字面量），既不撑大既有题目计数口径，也保证以后再加条目就自动进题 */
ALL_HERBS.filter(h=>h.cat).forEach((h,i)=>{
  const others=ALL_HERBS.filter(x=>x.n!==h.n);
  const wrong=others.slice((i*3)%20,(i*3)%20+3).map(x=>x.n);
  SITE_QS.push({q:`「${h.e.split("、")[0]}」是哪味药的功效？`,opts:[h.n,...wrong],a:h.n,
    fb:`${h.n}：${h.f}。${h.e}（归入「${h.cat}」类）`,root:`${h.n}载于${h.b}：${h.s}`});
});
BOOKS.slice(12).forEach((b,i)=>{
  const others=BOOKS.filter(x=>x.t!==b.t);
  const wrong=others.slice((i*2)%12,(i*2)%12+3).map(x=>x.t);
  BOOK_QS.push({q:`「${b.hl}」出自哪部典籍？`,opts:[b.t,...wrong],a:b.t,
    fb:`《${b.t}》${b.au}。${b.d}`,root:`《${b.t}》${b.hs}。药童领读：${b.why}`});
});
[...BOOK_QS,...SITE_QS].forEach(q=>{if(!q.root)for(const k in ROOTS){if(q.q.includes(k)){q.root=ROOTS[k];break;}}});
/* 辨药眼力：由相似药材数据生成选择题（一对两题，各考一味） */
function pairQuestions(l){
  const others=shuffleArr(HERBS.map(h=>h.n).filter(n=>n!==l.a&&n!==l.b)).slice(0,2);
  const fb=`${l.tip}<br><b>口诀：「${l.gj}」</b>`;
  return [
   {kind:"mcq",tag:"辨药眼力",q:`一味饮片：${l.sA}。它最可能是？`,opts:shuffleArr([l.a,l.b,...others]),a:l.a,fb},
   {kind:"mcq",tag:"辨药眼力",q:`一味药材：${l.sB}。它最可能是？`,opts:shuffleArr([l.a,l.b,...others]),a:l.b,fb}
  ];
}
function imgQuestion(h){
  const wrong=shuffleArr(HERBS.filter(x=>x.n!==h.n)).slice(0,3).map(x=>x.n);
  return {kind:"img",tag:"看图辨药",h,opts:shuffleArr([h.n,...wrong])};
}
function setGameMode(m){
  const g=window._game;
  if(g&&g.timer){clearInterval(g.timer);g.timer=null;} // 切模式先停表
  if(g&&g.readyTimer){clearInterval(g.readyTimer);g.readyTimer=null;} // 切模式也停开卷倒数
  const bp=$("#btnPractice"),bc=$("#btnContest");
  if(bp)bp.className=m==="practice"?"btn red":"btn ghost";
  if(bc)bc.className=m==="contest"?"btn red":"btn ghost";
  startGame(m);
}
/* ===== 管理后台接入（bencao-admin）：题库热更新 + 成绩/问答盲区上报 =====
   后台不在线（纯 GitHub Pages 访客）时全部静默降级，站点功能零影响 */
const ADMIN_API="http://localhost:8080/bencao-admin/api";
let REMOTE_QS=null; // 后台下发的题库，非空则竞赛文字题改从后台取
function syncQuestions(){
  try{
    const ctl=new AbortController();setTimeout(()=>ctl.abort(),2500);
    fetch(ADMIN_API+"/questions",{signal:ctl.signal}).then(r=>r.ok?r.json():null)
      .then(list=>{if(Array.isArray(list)&&list.length>=6)REMOTE_QS=list;}).catch(()=>{});
  }catch(e){}
}
function reportScore(s,total){ // 竞赛结算上报（打卡昵称作玩家名）
  try{fetch(ADMIN_API+"/score",{method:"POST",headers:{"Content-Type":"application/x-www-form-urlencoded"},
    body:new URLSearchParams({player:localStorage.getItem("bzNick")||"匿名游客",mode:"contest",score:s,total:total})}).catch(()=>{});}catch(e){}
}
function reportMiss(q){ // 问答盲区上报：药童答不上来的问题进后台"进化清单"
  try{fetch(ADMIN_API+"/kbmiss",{method:"POST",headers:{"Content-Type":"application/x-www-form-urlencoded"},
    body:new URLSearchParams({q:q})}).catch(()=>{});}catch(e){}
}
/* ===== 经典文献 AI 问答（RAG）=========================================
   流程：提问 → 本地检索本站经典原文 → POST /api/chat（API Key 只在服务端）
        → 模型只依据这些原文生成白话详解并标注出处 → 追加到对话
   后端离线 / 未配密钥 / 超时 / 检索为空 → 静默撤下占位，本地规则答案照常显示 */
const AI_API=ADMIN_API+"/chat";
let AI_READY=false,AI_ON=true,AI_CORPUS=null;
try{AI_ON=localStorage.getItem("bzAiOn")!=="0";}catch(e){}
const AI_STOP=new Set(["的","了","吗","呢","啊","吧","是","有","我","你","他","它","请","问","什","么","怎","样","何","哪","个","和","与","及","在","对","把","这","那","能","会","要","讲","说","下","上","中","为","以","之","乎","者","也","可","或","但","就","还","很","太","最","一","二","三"]);
function aiTokens(s){ // 中文无分词库：单字 + 二元组近似语义召回，停用字过滤
  s=norm(String(s||"").toLowerCase()).replace(/[^\u4e00-\u9fa5a-z0-9]/g,"");
  const set=new Set();
  for(let i=0;i<s.length;i++){
    const c=s[i];if(!AI_STOP.has(c))set.add(c);
    if(i+1<s.length){const b=s.slice(i,i+2);if(!AI_STOP.has(b))set.add(b);}
  }
  return [...set];
}
function buildCorpus(){ // 把全站结构化知识编成可检索的经典语料（懒加载，避开顶层 TDZ）
  const out=[];
  const add=(t,src,c)=>{if(!t||!c)return;const body=String(c).slice(0,700);
    out.push({t:String(t),src:String(src||t),c:body,tg:new Set(aiTokens(t)),cg:new Set(aiTokens(body))});};
  for(const k in BOOK_READS){ // 二十部经典原文选段（最高优先级语料）
    const b=BOOK_READS[k];
    (b.ps||[]).forEach(p=>add(`《${k}》· ${p.t}`,`《${k}》· ${p.t}`,`【原文】${p.s}\n【白话】${p.tr}`));
    if(b.g)add(`《${k}》· 药童导读`,`《${k}》`,b.g);
  }
  BOOKS.forEach(b=>add(`《${b.t}》`,`《${b.t}》`,`${b.au}。${b.d} 名句：「${b.hl}」${b.hs}。药童看点：${b.why}`));
  ALL_HERBS.forEach(h=>add(h.n,`药材 · ${h.n}`,`性味归经：${h.f}。功效分类：${h.cat||"药食同源"}。外观辨识：${h.x}。功效主治：${h.e}。经典出处：${h.s}。延伸阅读：${h.b}`));
  FORMULAS.forEach(f=>add(f.n,`名方 · ${f.n}`,`方书源流：${f.s}。${f.d}`));
  ACUP.forEach(a=>add(`穴位 · ${a.n}`,`穴位 · ${a.n}`,a.d));
  TOPICS.forEach(t=>add(t.n,`养生话题 · ${t.n}`,`${t.d} 参考：${t.b||""}`));
  LOOKALIKES.forEach(l=>add(`${l.a}与${l.b}的辨别`,`辨药 · ${l.a}/${l.b}`,`分辨要点：${l.tip} 口诀：${l.gj}`));
  [...BOOK_QS,...SITE_QS].forEach(q=>add(q.q,`考点 · ${q.a}`,`答案：${q.a}。解析：${q.fb||""} 根源：${q.root||""}`));
  return out;
}
function corpus(){if(!AI_CORPUS)AI_CORPUS=buildCorpus();return AI_CORPUS;}
function retrieve(q,k){ // 标题命中加权 3 倍、二元组加权 2 倍；相关性不足则判定「典籍未收录」，不让模型硬答
  const toks=aiTokens(q);
  const pool=corpus().map(e=>{
    let sc=0;
    toks.forEach(t=>{const w=t.length>1?2:1;if(e.tg.has(t))sc+=w*3;if(e.cg.has(t))sc+=w;});
    toks.filter(t=>t.length>1).forEach(t=>{if(e.t.indexOf(t)>=0)sc+=6;});
    return {e,sc};
  }).filter(x=>x.sc>=8).sort((a,b)=>b.sc-a.sc).slice(0,k||4);
  if(!pool.length||pool[0].sc<12)return []; // 纯闲聊/无关问题：省下这次调用，也避免幻觉
  return pool.map(x=>x.e);
}
function aiSan(s){ // 模型输出二次净化：只留白名单标签，防 XSS（后端已净化一次）
  return String(s||"").replace(/<script[\s\S]*?<\/script>/gi,"").replace(/<style[\s\S]*?<\/style>/gi,"")
    .replace(/\son[a-z]+\s*=\s*(?:"[^"]*"|'[^']*'|[^\s>]+)/gi,"").replace(/javascript\s*:/gi,"")
    .replace(/<\s*(\/?)\s*([a-z]+)[^>]*>/gi,(m,cl,t)=>["b","br","i","em","p","div"].indexOf(t.toLowerCase())>=0?`<${cl}${t.toLowerCase()}>`:"");
}
function aiState(txt,on){const el=$("#aiState");if(el){el.textContent=txt;el.classList.toggle("on",!!on);}}
function aiProbe(){ // 探测后端是否已配密钥，避免每次白等超时
  try{
    const ctl=new AbortController();setTimeout(()=>ctl.abort(),2500);
    fetch(AI_API,{signal:ctl.signal}).then(r=>r.ok?r.json():null).then(d=>{
      AI_READY=!!(d&&d.ok&&d.ready);
      aiState(AI_READY?`AI 已连接 · ${d.model||"模型"}`:"未配置密钥 · 本地典籍模式",AI_READY);
    }).catch(()=>{AI_READY=false;aiState("后端离线 · 本地典籍模式",false);});
  }catch(e){AI_READY=false;aiState("后端离线 · 本地典籍模式",false);}
}
function toggleAI(){
  AI_ON=!AI_ON;try{localStorage.setItem("bzAiOn",AI_ON?"1":"0");}catch(e){}
  const b=$("#aiToggle");if(b){b.textContent="AI 典籍详解 · "+(AI_ON?"开":"关");b.classList.toggle("off",!AI_ON);}
  if(AI_ON)aiProbe();
}
function localStyleSample(){ // 取上一条本地答案当语气锚点：模型照着本站腔调写，而不是自由发挥
  try{
    const box=$("#chatBox"),bds=box?box.querySelectorAll(".bd"):[];
    for(let i=bds.length-1;i>=0;i--){
      const t=String(bds[i].textContent||"").replace(/\s+/g," ").trim();
      if(t&&!/药童正翻检典籍|参考典籍：|药童引经详解/.test(t))return t.slice(0,260);
    }
  }catch(e){}
  return "";
}
function aiDeepDive(q,tag){
  if(!AI_ON||!AI_READY||tag==="intro"||tag==="fun"||tag==="detail")return;
  try{
    const hits=retrieve(q,4);
    if(!hits.length)return; // 检索为空就不问模型，从源头避免凭空编造
    const ctx=hits.map((h,i)=>`【${i+1}】来源：${h.src}\n${h.c}`).join("\n\n").slice(0,3500);
    const sources=[...new Set(hits.map(h=>h.src))];
    const sty=localStyleSample(); // 必须在创建占位气泡之前取，否则会拿到「翻检典籍」占位文字
    const box=bubble("本草智答 · 药童翻书详解",'<span class="ai-loading">药童正翻检典籍，稍等一忽儿〜</span>');
    const ctl=new AbortController();const timer=setTimeout(()=>ctl.abort(),15000);
    fetch(AI_API,{method:"POST",headers:{"Content-Type":"application/x-www-form-urlencoded"},
      body:new URLSearchParams({q:q,ctx:ctx,src:sources.join(" | "),sty:sty}),signal:ctl.signal})
      .then(r=>r.ok?r.json():null)
      .then(d=>{
        clearTimeout(timer);
        if(!d||!d.ok||!d.answer){if(box&&box.parentNode)box.parentNode.removeChild(box);return;}
        const tags=sources.slice(0,4).map(x=>`<b>◈ ${x}</b>`).join("　");
        const html=`<div class="ai-card"><span class="ai-tag">◈ 药童引经详解</span><br>${aiSan(d.answer)}<div class="ai-src">参考典籍：${tags}<br>本药童只照上面这几部典籍讲，药材剂量可别自己拿主意哦——具体请咨询执业中医师〜（${aiSan(d.model||"大模型")} 生成）</div></div>`;
        const bd=box&&box.querySelector?box.querySelector(".bd"):null;
        if(bd)bd.innerHTML=html;else box.innerHTML=`<div class="who">本草智答 · 药童翻书详解</div><div class="bd">${html}</div>`;
        const cb=$("#chatBox");if(cb)cb.scrollTop=cb.scrollHeight;
      })
      .catch(()=>{try{clearTimeout(timer);}catch(e){}if(box&&box.parentNode)box.parentNode.removeChild(box);});
  }catch(e){}
}
aiProbe();
function pickText(pool,n){ // 分层抽题：难题优先保底，再补基础题
  const hard=shuffleArr(pool.filter(q=>q.d)),easy=shuffleArr(pool.filter(q=>!q.d));
  return hard.concat(easy).slice(0,n);
}
function startGame(mode){
  mode=mode||((window._game&&window._game.mode)||"practice");
  const qs=buildPaper(mode==="contest"); // 练习与竞赛共用同一套混合卷生成器（练习 14 题/竞赛 21 题），仅计规则不同
  const bot=$("#gameBot");if(bot)bot.style.display=mode==="contest"?"flex":"none"; // 练习不打扰：小药童只在竞赛登场当裁判
  window._game={qs,i:0,score:0,mode,timer:null,readyTimer:null,started:false,finished:false};
  if(!PAGE_MOUNTED.game)return; // 尚未进入试炼页：只备好卷子，不渲染题面、不加载题图
  // 练习：点「练习模式」按钮即出题；竞赛：先给准备预警页，确认「开始答题」后才开卷读秒
  if(mode==="contest")renderContestReady();
  else{window._game.started=true;renderGameQ();}
}
/* 待机屏：进入试炼页先不出题、不计时，等用户点模式按钮 */
function renderGameIdle(){
  const box=$("#gameArea");if(!box)return;
  box.innerHTML=`
    <div class="game-idle">
      <div class="gi-seal">试</div>
      <h3>请先选一种试炼方式</h3>
      <p>题目不会自己蹦出来〜点上方按钮才开卷：<b>练习模式</b>点下即出题；<b>知识竞赛</b>会先给你一张准备预警页，确认「开始答题」后才开始 ${CONTEST_LIMIT} 秒读秒。</p>
      <div class="gi-grid">
        <div><b>🌿 练习模式</b>14 题混合卷 · 不限时<br>答完即见解析，还能追问药童</div>
        <div><b>⏱ 知识竞赛</b>21 题 · 每题限时 ${CONTEST_LIMIT} 秒<br>先预警、再开卷，答完领称号</div>
      </div>
      <p class="gi-note">◈ 此刻既没有题面、也没有倒计时，可以先去翻翻经典，准备好了再点按钮。</p>
    </div>`;
}
/* 竞赛开卷预警：确认前不出题、不计时，给用户一个准备缓冲 */
function renderContestReady(){
  const g=window._game,box=$("#gameArea");if(!g||!box)return;
  const say=$("#gameBotSay");if(say)say.textContent="先别急着落笔！看清规矩，点「开始答题」我才开卷读秒〜";
  box.innerHTML=`
    <div class="game-ready">
      <span class="gr-tag">⚠ 开 卷 预 警</span>
      <h3>知识竞赛 · 请准备</h3>
      <p>小药童提醒：点下方「开始答题」后，题面立刻出现并<b>马上开始读秒</b>，中途不能暂停。先确认下面几条：</p>
      <ul class="gr-list">
        <li>共 <b>${g.qs.length} 题</b>：看图辨药 + 经典考点 + 全站通 + 辨药眼力</li>
        <li>每题限时 <b>${CONTEST_LIMIT} 秒</b>，超时判未中并自动进入下一题</li>
        <li>答完自动结算、记录最佳成绩，可一键复制战帖</li>
        <li>切到别的页面会停表，回来重新读秒；建议找个不被打扰的空档</li>
      </ul>
      <div class="gr-btns">
        <button class="btn red" onclick="beginContest()">我准备好了 · 开始答题 →</button>
        <button class="btn ghost" onclick="setGameMode('practice')">改去练习模式</button>
      </div>
      <p class="gr-note">◈ 还没点「开始答题」之前，不会有题目，也不会消耗时间。</p>
    </div>`;
}
/* 开卷倒数：3 → 2 → 1，倒数归零才真正出题并启动每题计时 */
function beginContest(){
  const g=window._game,box=$("#gameArea");
  if(!g||g.mode!=="contest"||!box)return;
  if(g.readyTimer){clearInterval(g.readyTimer);g.readyTimer=null;}
  const say=$("#gameBotSay");if(say)say.textContent="三、二、一——开卷！眼疾手快，别让药跑喽〜";
  let n=3;
  const paint=()=>{box.innerHTML=`<div class="game-countdown"><div class="gc-num">${n}</div><p>题面即将出现 · 准备接招</p></div>`;};
  paint();
  g.readyTimer=setInterval(()=>{
    n--;
    if(n<=0){clearInterval(g.readyTimer);g.readyTimer=null;g.started=true;renderGameQ();return;}
    paint();
  },800);
}
/* 混合出卷：练习 2 图像 + 5 经典 + 5 全站 + 2 辨药眼力 = 14 题；竞赛 3 + 8 + 8 + 2 = 21 题，难题保底打乱；竞赛后台题库最多热替换 8 道文字题，不足由内置补齐 */
function buildPaper(contest){
  const nImg=contest?3:2,nBook=contest?8:5,nSite=contest?8:5;
  const imgs=shuffleArr(HERBS).slice(0,nImg).map(imgQuestion);
  const local=(q,tag)=>({kind:"mcq",tag,q:q.q,opts:shuffleArr(q.opts),a:q.a,fb:q.fb,root:q.root});
  let texts;
  if(contest&&REMOTE_QS&&REMOTE_QS.length>=4){
    const toMcq=q=>({kind:"mcq",tag:q.tag||"后台题库",q:q.q,opts:shuffleArr(q.opts),a:q.a,fb:q.fb||""});
    const rem=pickText(REMOTE_QS,8).map(toMcq);
    const pool=shuffleArr(pickText(BOOK_QS,nBook).map(q=>local(q,"经典考点")).concat(pickText(SITE_QS,nSite).map(q=>local(q,"全站通"))));
    texts=rem.concat(pool.slice(0,nBook+nSite-rem.length));
  }else{
    texts=pickText(BOOK_QS,nBook).map(q=>local(q,"经典考点")).concat(pickText(SITE_QS,nSite).map(q=>local(q,"全站通")));
  }
  const pairs=shuffleArr(LOOKALIKES).slice(0,2).map(l=>pairQuestions(l)[Math.random()<.5?0:1]);
  return shuffleArr([...imgs,...texts,...pairs]);
}
function renderGameQ(){
  const g=window._game;
  if(g.timer){clearInterval(g.timer);g.timer=null;}
  if(g.readyTimer){clearInterval(g.readyTimer);g.readyTimer=null;}
  if(g.i>=g.qs.length)return endGame();
  const q=g.qs[g.i];
  const contest=g.mode==="contest";
  const body=q.kind==="mcq"
    ? `<div class="game-qtext"><span class="qt-tag">◈ ${q.tag} ◈</span><br>${q.q}</div>`
    : `<div class="game-pic" id="gamePic"><img src="assets/herbs/${HERB_IMG[q.h.n]}.webp" alt="本草工笔插画" decoding="async" fetchpriority="high"></div>`;
  $("#gameArea").innerHTML=`
    ${contest?`<div class="game-timer"><div class="bar"><i id="tmBar" style="width:100%"></i></div><span class="sec" id="tmSec">${CONTEST_LIMIT}s</span></div>`:""}
    <div class="game-score"><div><b>${g.score}</b><span>当前得分</span></div><div><b>${g.i+1} / ${g.qs.length}</b><span>第几道题</span></div></div>
    <div class="game-round">◈ 第 ${g.i+1} 题 · ${q.kind==="mcq"?q.tag:"请辨识"}${contest?" · 限时作答":" · 不限时"} ◈</div>
    ${body}
    <div class="game-opts">${q.opts.map(o=>`<button onclick="pickGame('${o}')">${o}</button>`).join("")}</div>
    <div class="game-fb" id="gameFb">${contest?"竞赛进行中 · 眼疾手快，超时算未中〜":`${g.qs.length} 题混合卷 · 不限时作答，答完即见药童解析`}</div>`;
  gameReact("ready",g.i+1);
  if(contest)startTimer();
}
function startTimer(){
  const g=window._game;let left=CONTEST_LIMIT;
  const bar=$("#tmBar"),sec=$("#tmSec");
  const tick=()=>{
    left-=0.1;
    if(left<=0){clearInterval(g.timer);g.timer=null;pickGame(null);return;} // 超时判负
    if(bar){bar.style.width=(left/CONTEST_LIMIT*100)+"%";if(left<=3)bar.classList.add("low");}
    if(sec)sec.textContent=Math.ceil(left)+"s";
  };
  g.timer=setInterval(tick,100);
}
function pickGame(name){
  const g=window._game,q=g.qs[g.i];
  const contest=g.mode==="contest";
  if(g.timer){clearInterval(g.timer);g.timer=null;}
  const ansN=q.kind==="mcq"?q.a:q.h.n;
  const right=name===ansN;
  const btns=document.querySelectorAll("#gameArea .game-opts button");
  btns.forEach(b=>{b.disabled=true;if(b.textContent===ansN)b.classList.add("ok");});
  if(right)g.score++;
  else{
    btns.forEach(b=>{if(b.textContent===name)b.classList.add("bad");});
    const pic=$("#gamePic");if(pic)pic.classList.add("shake");
  }
  if(contest){
    // 竞赛节奏：短反馈自动进入下一题，不打断比拼
    $("#gameFb").innerHTML=right?`<b class="good">✔ 中！</b>`:(name===null?`⏱ 超时！正解：<b>${ansN}</b>`:`✘ 差矣，正解：<b>${ansN}</b>`);
    gameReact(right?"ok":(name===null?"timeout":"bad"));
    unlockHerb(q.kind==="img"&&right?q.h.n:null,true);
    setTimeout(nextGame,q.kind==="mcq"?1600:1200);
    return;
  }
  if(q.kind==="img"&&right)unlockHerb(q.h.n);
  gameReact(right?"ok":"bad");
  const askQ=q.kind==="img"?q.h.n:`详细讲讲：${q.q}`; // 没看懂？带着题目去问答页追问药童
  $("#gameFb").innerHTML=(right?`<b class="good">✔ ${pick(GAME_OK)}</b>`:`✘ ${pick(q.kind==="mcq"?GAME_MCQ_BAD:GAME_BAD)}<b>${ansN}</b>`)
    +(q.kind==="mcq"?`<br>${q.fb}`:`<br><b>${q.h.n}</b> · ${q.h.f}<br>◈ 外观辨识：${q.h.x}<br>${q.h.e}`)
    +`<div style="margin-top:8px;display:flex;gap:8px;flex-wrap:wrap"><button class="btn ghost" onclick="nextGame()">${g.i>=g.qs.length-1?"看成绩 →":"下一题 →"}</button><button class="btn ghost" onclick="askKB('${askQ}')">没看懂？去问药童详解 →</button></div>`;
}
function nextGame(){window._game.i++;renderGameQ();}
function endGame(){
  const g=window._game;
  g.finished=true;
  if(g.timer){clearInterval(g.timer);g.timer=null;}
  if(g.readyTimer){clearInterval(g.readyTimer);g.readyTimer=null;}
  const s=g.score,contest=g.mode==="contest",full=g.qs.length; // 题量随模式：练习 14 / 竞赛 21
  const hi=Math.ceil(full*.75),mid=Math.ceil(full*.5),lo=Math.ceil(full*.3); // 称号档位按题量等比换算（12 题时即 9/6/4）
  if(contest){
    let best=null;try{best=JSON.parse(localStorage.getItem("bzContestBest")||"null");}catch(e){}
    if(!best||s>best.s){best={s,n:full,d:new Date().getMonth()+1+"月"+new Date().getDate()+"日"};localStorage.setItem("bzContestBest",JSON.stringify(best));}
    reportScore(s,full); // 成绩同步管理后台（离线静默）
  }
  const r=s===full?["坐堂神医",`${full} 问全中！混合题库都难不倒你，李时珍看了都想收你当徒弟，药童甘愿给您打下手〜`]
    :s>=hi?["游方郎中","走方行医的眼力已经有了！经典考点与全站通也难不住你，再翻翻荐读里的选段，便可出师。"]
    :s>=mid?["药童同门","基本功扎实！论辈分和药童算同门师兄弟——经典选段再补补课，下轮冲高分。"]
    :s>=lo?["抓药学徒","柜台后站稳了！常来药圃转转、翻翻「经典荐读」的阅读选段，眼力与学问都是养出来的〜"]
    :["药圃看门的","药童替你捏一把汗……不过没关系，荐读页每部书都能点开读选段，读完再来战！"];
  try{if(!contest){const b=JSON.parse(localStorage.getItem("bzGameBest")||"null");if(!b||s>b.s)localStorage.setItem("bzGameBest",JSON.stringify({s,t:r[0]}));}}catch(e){}
  gameReact(s>=hi?"end-ok":s>=mid?"end-mid":"end-bad");
  $("#gameArea").innerHTML=`
    <div class="game-end">
      <div class="game-score"><div><b>${s}</b><span>答对</span></div><div><b>${full}</b><span>总题数</span></div></div>
      <div class="title">${r[0]}</div>
      <div class="seal">百草园 · 授</div>
      <p>${contest?"（知识竞赛 · 每题限时 "+CONTEST_LIMIT+" 秒）":""}${r[1]}</p>
      ${contest?`<p style="font-size:12.5px;color:var(--ink3)">◈ 竞赛最佳成绩已记入名帖：${s} / ${full}</p>`:""}
      <button class="btn red" onclick="startGame()">${contest?"再战一轮":"再来一轮"}</button>
      <button class="btn ghost" onclick="copyChallenge(${s},'${r[0]}',${full})">📣 发起挑战 · 复制战帖</button>
      <button class="btn ghost" onclick="go('read')">读读经典 →</button>
      <button class="btn ghost" onclick="go('album')">翻翻图鉴 →</button>
      <button class="btn ghost" onclick="go('checkin')">去打卡 →</button>
    </div>`;
}
/* 挑战战帖：一键复制成绩+称号+链接，转发好友过招 */
function copyChallenge(s,title,total){
  const txt=`【本草战帖 · 岐黄论剑】我在「本草智答」知识竞赛中答对 ${s}/${total||21}，荣获「${title}」称号！识体质、问本草、读经典、战竞赛——你也来过过招？药童在百草园等你想胜负〜 ${location.href.split("#")[0]}`;
  const done=()=>{const t=document.createElement("div");t.className="chal-toast";t.textContent="⚔ 战帖已复制！快去粘贴给你的好友吧";document.body.appendChild(t);requestAnimationFrame(()=>t.classList.add("show"));setTimeout(()=>{t.classList.remove("show");setTimeout(()=>t.remove(),400);},2400);};
  const fallback=()=>{const ta=document.createElement("textarea");ta.value=txt;ta.style.position="fixed";ta.style.opacity="0";document.body.appendChild(ta);ta.select();try{document.execCommand("copy");done();}catch(e){}ta.remove();};
  if(navigator.clipboard&&navigator.clipboard.writeText){navigator.clipboard.writeText(txt).then(done).catch(fallback);}else fallback();
}
/* MPA：游戏页由 bootstrap 经 PAGE_INIT.game 渲染 idle，无需全局预载 */
setTimeout(syncQuestions,0); // 顺路尝试从管理后台拉最新题库（后台不在线则用内置题库）

/* ===== 本草图鉴集章系统 ===== */
/* 注意：_alStore 必须用 var——每日本草 IIFE 在脚本前部就会调用 unlockHerb，let 会落入 TDZ 直接崩页 */
var _alStore=null;
function alGet(){
  if(_alStore)return _alStore;
  try{_alStore=JSON.parse(localStorage.getItem("bzAlbum")||"{}");}catch(e){_alStore={};}
  return _alStore;
}
function alSave(d){_alStore=d;try{localStorage.setItem("bzAlbum",JSON.stringify(d));}catch(e){}}
function alCount(){return Object.keys(alGet()).length;}
const AL_TITLES=[[14,"百草园主","十四味本草尽收囊中"],[10,"百草通","再集四味就满园了"],[5,"渐入佳境","过半在望，继续加油"],[1,"初识百草","每次相遇都会点亮一枚"],[0,"未启程","问药童、玩辨药都能集章"]];
function unlockHerb(name,silent){
  if(!name)return false;
  const d=alGet();
  if(d[name])return false;
  d[name]=new Date().getMonth()+1+"月"+new Date().getDate()+"日";
  alSave(d);
  const n=alCount();
  if(!silent){
    let extra="";
    if(n===5)extra="！集满5味，渐入佳境〜";
    else if(n===10)extra="！十味入手，堪称百草通！";
    else if(n===14)extra="！十四味全收，百草园主就是你了！";
    alToast("◈ 集章成功 · "+name+extra);
  }
  return true;
}
function alToast(msg){
  const t=document.createElement("div");
  t.className="al-toast";t.textContent=msg;
  document.body.appendChild(t);
  setTimeout(()=>t.remove(),2600);
}
/* ===== 岐黄打卡（阅读打卡 · 文化节读者互动） ===== */
const CI_QUOTES=[
 ["读书不如读无字之书，识药先识身边之药","药童语录"],
 ["善言天者，必应于人；善言古者，必验于今","《素问·气交变大论》"],
 ["上工治未病，不治已病","《黄帝内经》"],
 ["安身之本，必资于食；救疾之速，必凭于药","孙思邈《千金要方》"],
 ["不知易，不足以言太医","孙思邈"],
 ["纸上得来终觉浅，绝知此事要躬行","陆游《冬夜读书示子聿》"],
 ["读书之乐何处寻，数点梅花天地心","翁森《四时读书乐》"],
 ["本草虽微，可养性命；经典虽古，可启新知","药童语录"]
];
function ciGet(){try{return JSON.parse(localStorage.getItem("bzCheckin")||"null")||{d:[]};}catch(e){return{d:[]};}}
function ciSave(c){try{localStorage.setItem("bzCheckin",JSON.stringify(c));}catch(e){}}
function ciKey(dt){dt=dt||new Date();return dt.getFullYear()+"-"+(dt.getMonth()+1)+"-"+dt.getDate();}
function ciStreak(){
  const set=new Set(ciGet().d);
  let n=0;const cur=new Date();
  if(!set.has(ciKey(cur)))cur.setDate(cur.getDate()-1); // 今天未打不影响昨日连击
  while(set.has(ciKey(cur))){n++;cur.setDate(cur.getDate()-1);}
  return n;
}
function doCheckin(){
  const c=ciGet(),k=ciKey();
  if(c.d.includes(k)){alToast("◈ 今日已打过卡啦，明早再来〜");return;}
  c.d.push(k);ciSave(c);
  // 打卡联动：静默点亮今日本草章（若未集），合并一条提示
  const doy=Math.floor((Date.now()-new Date(new Date().getFullYear(),0,0))/864e5);
  const h=HERBS[doy%HERBS.length];
  const fresh=unlockHerb(h.n,true);
  const n=alCount();
  alToast("◈ 打卡成功 · 连续 "+ciStreak()+" 天"+(fresh?"，顺手点亮「"+h.n+"」图鉴印（"+n+"/14）":""));
  renderCheckin();ciStatSync();
}
function ciStatSync(){const el=$("#ciStat");if(el)el.textContent=ciStreak();}
function renderCheckin(){
  const c=ciGet(),k=ciKey(),done=c.d.includes(k);
  const streak=ciStreak(),total=c.d.length;
  const n=alCount(),t=AL_TITLES.find(x=>n>=x[0]);
  let g=null;try{g=JSON.parse(localStorage.getItem("bzContestBest")||"null");}catch(e){}
  const p=physGet();
  const q=CI_QUOTES[total%CI_QUOTES.length];
  // 本月日历：周一至周日表头，按当月实际排布
  const now=new Date(),y=now.getFullYear(),m=now.getMonth();
  const first=new Date(y,m,1),days=new Date(y,m+1,0).getDate();
  let lead=(first.getDay()+6)%7; // 周一=0
  const hitSet=new Set(c.d);
  let cells=["一","二","三","四","五","六","日"].map(w=>`<div class="cell wk">${w}</div>`).join("");
  for(let i=0;i<lead;i++)cells+='<div class="cell"></div>';
  for(let d=1;d<=days;d++){
    const key=y+"-"+(m+1)+"-"+d,hit=hitSet.has(key),today=d===now.getDate();
    cells+=`<div class="cell${hit?" hit":""}${today?" today":""}" title="${m+1}月${d}日${hit?" · 已打卡":""}">${d}</div>`;
  }
  $("#checkinArea").innerHTML=`
    <div class="ci-banner">◈ 中医药文化 · 读者阅读打卡专区 —— 每日一格，把岐黄之学读成习惯 ◈</div>
    <div class="ci-stats">
      <div><b>${streak}</b><span>连续打卡</span></div>
      <div><b>${total}</b><span>累计天数</span></div>
      <div><b>${n} / 14</b><span>本草集章</span></div>
      <div><b>${g?g.s+" / "+(g.n||12):"—"}</b><span>竞赛最佳</span></div>
      <div><b>${p?p.n.slice(0,2):"—"}</b><span>体质档案</span></div>
    </div>
    <div style="text-align:center;margin-bottom:20px">
      ${done?`<button class="btn ghost" style="cursor:default">✓ 今日已打卡 · 明日再来</button>`
        :`<button class="btn red" onclick="doCheckin()">◈ 今日签到 · 点亮一格</button>`}
    </div>
    <div class="ci-month">${y} 年 ${m+1} 月</div>
    <div class="ci-cal">${cells}</div>
    <div class="ci-quote">「${q[0]}」</div>
    <div class="ci-quote-src">—— ${q[1]}</div>
    <div style="display:flex;gap:10px;justify-content:center;flex-wrap:wrap;margin-top:6px">
      <button class="btn ghost" onclick="makePoster()">生成我的名帖 →</button>
      <button class="btn ghost" onclick="go('game')">去知识竞赛 →</button>
      <button class="btn ghost" onclick="go('album')">翻翻图鉴 →</button>
    </div>`;
}
function renderAlbum(){
  const d=alGet(),n=alCount();
  const t=AL_TITLES.find(x=>n>=x[0]);
  $("#albumArea").innerHTML=`
    <div class="al-progress">
      <div class="num">${n}<small> / 14</small></div>
      <div class="bar"><i style="width:${Math.round(n/14*100)}%"></i></div>
      <div class="title"><b>${t[1]}</b><span>${t[2]}</span></div>
    </div>
    <div style="text-align:right;margin-bottom:10px"><button class="btn ghost" style="padding:8px 18px;font-size:13px" onclick="makePoster()">◈ 生成我的名帖</button></div>
    <div class="album-grid">${HERBS.map(h=>{
      const got=d[h.n];
      return got?`<div class="al-card"><div class="al-pic"><img src="assets/herbs/${HERB_IMG[h.n]}.webp" alt="${h.n}" loading="lazy" decoding="async"></div><div class="al-seal">集于${got}</div><b>${h.n}</b><span>${h.f.split("，")[0]}</span></div>`
        :`<div class="al-card locked" style="cursor:pointer" onclick="askKB('${h.n}')" title="问问药童：${h.n}是哪位？"><div class="al-pic"><img src="assets/herbs/${HERB_IMG[h.n]}.webp" alt="未解锁" loading="lazy" decoding="async"><span class="al-q">？</span></div><b>？？？</b><span>点我 · 去问药童点亮</span></div>`;
    }).join("")}</div>
    <p style="text-align:center;font-size:12.5px;color:var(--ink3);margin-top:16px">集章途径：问答里问本草 · 百草试炼答对 · 岐黄打卡点亮每日本草 · 图鉴灰卡可点击直达问答　|　<a href="#" onclick="go('checkin');return false" style="color:var(--green)">去打卡 →</a>　<a href="#" onclick="go('game');return false" style="color:var(--green)">去药圃考考眼力 →</a></p>
    <div style="text-align:center;margin-top:16px"><button class="btn red" onclick="makePoster()">◈ 生成我的本草名帖</button></div>`;
}
function physGet(){try{return JSON.parse(localStorage.getItem("bzPhysique")||"null");}catch(e){return null;}}
/* 回填：首页图鉴计数 + 体质档案徽标（首页）与提示条（辨识页） */
(function(){
  const el=$("#alStat");if(el)el.textContent=alCount();
  ciStatSync();
  const p=physGet();if(!p)return;
  const badge=$("#physBadge");
  if(badge){badge.style.display="inline-flex";badge.innerHTML=`◈ 你的体质档案：<b>${p.n}</b>（${p.j}）· ${p.d}辨识 · 点击复查`;}
})();
/* ===== 首页功能卡 · 真实进度回填（首次进入 / 每次返回首页刷新） ===== */
function refreshFeatMeta(){
  try{
    const put=(k,txt,done)=>{
      const el=document.querySelector('.feat [data-meta="'+k+'"]');
      if(!el)return;
      el.textContent=txt;
      if(el.classList)el.classList.toggle("done",!!done);
    };
    let p=null,best=null;
    try{p=physGet();}catch(e){}
    try{best=JSON.parse(localStorage.getItem("bzContestBest")||"null");}catch(e){}
    const doy=Math.floor((Date.now()-new Date(new Date().getFullYear(),0,0))/864e5);
    const h=HERBS[doy%HERBS.length],stamps=alCount(),streak=ciStreak();
    const doneCi=ciGet().d.includes(ciKey());
    put("quiz",p?`已合参 · ${p.n}（${p.j}）· 契合书目已点亮`:"未测评 · 📷 面象望诊参考 + 量表合参（约 1 分钟）",!!p);
    put("chat",`${corpus().length} 条典籍语料 · 可追问详解`,false);
    put("game",best?`竞赛最佳 ${best.s} 分 / ${best.n} 题`:"练习 14 题 · 竞赛 21 题",!!best);
    put("album",`已点亮 ${stamps} / ${HERBS.length} 味`,stamps>0);
    put("read",`${BOOKS.length} 部典籍`+(p?` · 契合${p.n}已点亮`:" · 让小药童识体质后点亮契合书目"),!!p);
    put("checkin",`连续 ${streak} 天 · 今日${doneCi?"已":"未"}打卡`,doneCi);
    put("food",`今日一味 · ${h.n}（${h.f.split(" · ")[0]}）`,false);
    put("formula",`${FORMULAS.length} 首名方 · ${FORMULAS[0].n}等`,false);
    put("acup",`${ACUP.length} 处要穴 · ${ACUP.map(a=>a.n).join(" / ")}`,false);
  }catch(e){}
}
refreshFeatMeta();
function syncStats(){
  try{
    const set=(id,txt)=>{const el=document.getElementById(id);if(el)el.textContent=txt;};
    set("hbStat",ALL_HERBS.length);   // 本草：全站知识口径（14 味有图 + 26 味文字）
    set("fmStat",FORMULAS.length);    // 名方：随 FORMULAS 数据动态
    set("acStat",ACUP.length);        // 穴位：随 ACUP 数据动态
    set("bkStat",BOOKS.length);       // 经典：随 BOOKS 数据动态（含 push 扩展）
  }catch(e){}
}
syncStats();
function restorePhys(){
  const p=physGet();if(!p)return;
  const lp=$("#lastPhys");
  const qp=encodeURIComponent(p.n.replace("质","")+"体质怎么调理");
  if(lp){lp.style.display="block";lp.innerHTML=`◈ 上次辨识：<b>${p.n}</b>（${p.j}）· ${p.d}${p.way?"（"+p.way+"）":""} —— <a href="chat.html?q=${qp}">咨询药童调理</a> · 下方任选一种方式重新辨识即可更新档案并刷新荐读`;}
}

/* ===== 本草名帖 · 一键生成分享海报（纯前端 canvas，无服务器） ===== */
function rr(x,a,b,w,h,r){x.beginPath();x.moveTo(a+r,b);x.arcTo(a+w,b,a+w,b+h,r);x.arcTo(a+w,b+h,a,b+h,r);x.arcTo(a,b+h,a,b,r);x.arcTo(a,b,a+w,b,r);x.closePath();}
function posterData(){
  const p=physGet(),al=alGet(),names=Object.keys(al),n=names.length;
  const t=AL_TITLES.find(x=>n>=x[0]);
  let g=null;try{g=JSON.parse(localStorage.getItem("bzGameBest")||"null");}catch(e){}
  let cb=null;try{cb=JSON.parse(localStorage.getItem("bzContestBest")||"null");}catch(e){}
  const ci=ciStreak(),ciTotal=ciGet().d.length;
  const doy=Math.floor((Date.now()-new Date(new Date().getFullYear(),0,0))/864e5);
  const season=seasonOf(),sRec=SEASON_READS[season];
  return {p,names,n,t,g,cb,ci,ciTotal,season,book:sRec.list[doy%sRec.list.length]};
}
function drawPoster(D,qrImg){
  const W=600,H=880,c=document.createElement("canvas");c.width=W;c.height=H;
  const x=c.getContext("2d");
  const ZH='"Ma Shan Zheng","Noto Serif SC","STSong",serif', SONG='"Noto Serif SC","STSong",serif';
  /* 纸底 + 水印 + 双边框 */
  x.fillStyle="#F5F1E8";x.fillRect(0,0,W,H);
  x.textAlign="center";x.textBaseline="alphabetic";
  x.fillStyle="rgba(47,93,80,.05)";x.font="230px "+ZH;x.fillText("帖",W/2,H/2+95);
  x.strokeStyle="rgba(154,123,63,.55)";x.lineWidth=2;x.strokeRect(18,18,W-36,H-36);
  x.strokeStyle="rgba(154,123,63,.22)";x.lineWidth=1;x.strokeRect(28,28,W-56,H-56);
  /* 题名 */
  x.fillStyle="#2B2B26";x.font="56px "+ZH;x.fillText("本 草 名 帖",W/2,122);
  x.fillStyle="#9A7B3F";x.font="19px "+ZH;x.fillText("—— 本草智答 · 百草园谨制 ——",W/2,158);
  x.strokeStyle="rgba(154,123,63,.35)";x.beginPath();x.moveTo(130,192);x.lineTo(W/2-18,192);x.moveTo(W/2+18,192);x.lineTo(W-130,192);x.stroke();
  x.fillStyle="#9A7B3F";x.font="15px "+ZH;x.fillText("◈",W/2,197);
  /* 体质 */
  if(D.p){
    x.fillStyle="#A63E28";x.font="44px "+ZH;x.fillText(D.p.n+"（"+D.p.j+"）",W/2,254);
    x.fillStyle="#98958A";x.font="13px "+SONG;x.fillText("辨识于 "+D.p.d+" · 中华中医药学会九种体质量表",W/2,284);
  }else{
    x.fillStyle="#98958A";x.font="16px "+SONG;x.fillText("尚未辨识体质 · 9 题速测等你作答",W/2,260);
  }
  /* 辨药（练习最佳 + 竞赛最佳）+ 集章 + 打卡 */
  x.fillStyle="#2B2B26";x.font="20px "+SONG;
  x.fillText(D.g?("辨药小试 · 最佳 "+D.g.s+" 题 · "+D.g.t):"药圃初来乍到 · 尚未留名",W/2,334);
  if(D.cb)x.fillText("知识竞赛 · 最佳 "+D.cb.s+" / "+(D.cb.n||12)+(D.cb.d?"（"+D.cb.d+"）":""),W/2,362);
  x.fillText("集章 "+D.n+" / 14 · "+D.t[1]+(D.ciTotal?" · 打卡累计 "+D.ciTotal+" 天":""),W/2,388);
  /* 十四枚小印阵 */
  const cell=44,cols=7,gx=W/2-cols*cell/2,gy=412;
  for(let i=0;i<14;i++){
    const cx=gx+(i%cols)*cell+(cell-36)/2,cy=gy+Math.floor(i/cols)*cell,nm=HERBS[i].n;
    if(D.names.includes(nm)){
      x.fillStyle="#A63E28";rr(x,cx,cy,36,36,6);x.fill();
      x.fillStyle="#FBF3E4";x.font="20px "+ZH;x.fillText(nm[0],cx+18,cy+27);
    }else{
      x.strokeStyle="rgba(152,149,138,.5)";x.setLineDash([3,3]);rr(x,cx,cy,36,36,6);x.stroke();x.setLineDash([]);
      x.fillStyle="rgba(152,149,138,.7)";x.font="16px "+ZH;x.fillText("？",cx+18,cy+26);
    }
  }
  /* 今日荐读 + 名句 */
  x.fillStyle="#9A7B3F";x.font="15px "+SONG;x.fillText("时值"+D.season+" · 今日荐读",W/2,548);
  const bk=BOOKS.find(b=>b.t===D.book);
  x.fillStyle="#2B2B26";x.font="32px "+ZH;x.fillText("《"+bk.t+"》",W/2,590);
  x.fillStyle="#6B6A60";x.font="15px "+SONG;
  const q="「"+bk.hl+"」";
  if(q.length<=16)x.fillText(q,W/2,636);
  else{const mid=Math.ceil(q.length/2);x.fillText(q.slice(0,mid),W/2,636);x.fillText(q.slice(mid),W/2,662);}
  /* 二维码：扫码同游百草园 */
  if(qrImg&&qrImg.complete&&qrImg.naturalWidth){
    const QS=104,qx=W/2-QS/2,qy=694;
    x.fillStyle="#FDFBF4";rr(x,qx-8,qy-8,QS+16,QS+16,8);x.fill();
    x.strokeStyle="rgba(154,123,63,.4)";x.lineWidth=1;x.strokeRect(qx-8.5,qy-8.5,QS+17,QS+17);
    x.drawImage(qrImg,qx,qy,QS,QS);
    x.fillStyle="#9A7B3F";x.font="14px "+SONG;x.fillText("◈ 扫码同游百草园 · 中医药文化读者互动 ◈",W/2,qy+QS+28);
  }
  /* 落款 + 大朱印 */
  const now=new Date();
  x.fillStyle="#98958A";x.font="13px "+SONG;
  x.fillText(now.getFullYear()+" 年 "+(now.getMonth()+1)+" 月 "+now.getDate()+" 日 · 本草智答谨识",W/2,H-40);
  x.save();x.translate(W-92,H-108);x.rotate(-0.08);
  x.fillStyle="#A63E28";rr(x,-33,-33,66,66,7);x.fill();
  x.fillStyle="#FBF3E4";x.font="23px "+ZH;
  x.fillText("本",-16,-13);x.fillText("草",16,-13);x.fillText("智",-16,17);x.fillText("答",16,17);
  x.restore();
  try{return c.toDataURL("image/png");}
  catch(e){if(qrImg)return drawPoster(D,null);throw e;} /* file:// 下外部图片会污染画布 → 去码重画 */
}
function showPoster(url){
  let m=$("#posterMask");
  if(!m){
    m=document.createElement("div");m.id="posterMask";
    m.innerHTML='<img alt="本草名帖"><p class="tip">长按图片可保存 · 或点击下载</p><a class="btn red" download="本草名帖.png">下 载 名 帖</a>';
    m.addEventListener("click",e=>{if(e.target===m)m.classList.remove("on");});
    document.body.appendChild(m);
  }
  m.querySelector("img").src=url;
  m.querySelector("a").href=url;
  m.classList.add("on");
}
